/* AUTO-GENERATED by scripts/gen-iot-examples.mjs — do not edit.
   Source of truth: iot-examples.manifest.json → the real composition files under apps/web/src/examples/iot/ */
export const iotExampleSource: Record<string, string> = {
  "state-honesty": "/**\n * Requested is not confirmed.\n *\n * Press a control and watch two values that most device UIs collapse into one: what you ASKED for, and\n * what the device last REPORTED. The confirmed value changes only when the device confirms it. An\n * acknowledgement (\"I got that\") is not a confirmation, a timeout is not \"off\", and a device that\n * stopped answering is `unreachable` rather than quietly assumed to have obeyed.\n *\n * Everything here is scripted in the browser. `@kinetixui/iot` has no transport, so no request leaves\n * the page, and no delay below is a real network delay.\n */\nconst STAGE_WORD: Record<string, { state: ShowcaseState; word: string }> = {\n  requested: { state: \"pending\", word: \"Requested, not yet confirmed\" },\n  retrying: { state: \"pending\", word: \"Retrying, not yet confirmed\" },\n  acknowledged: { state: \"pending\", word: \"Acknowledged, not yet confirmed\" },\n  failed: { state: \"warning\", word: \"Failed. The device did not change.\" },\n  \"timed-out\": { state: \"warning\", word: \"Timed out. No answer yet.\" },\n  unreachable: { state: \"offline\", word: \"Unreachable. Last confirmed value shown.\" },\n};\n\n/** One device, two values side by side: what it REPORTED (big, solid) and what you ASKED for (dashed, worded). */\nfunction Panel({ title, note, binding, children }: { title: string; note: string; binding: ControlBinding; children: React.ReactNode }) {\n  const { command, confirmed, requested, format } = binding;\n  const stage = command && binding.unsettled ? STAGE_WORD[command.lifecycle.stage] : undefined;\n  const asked = requested !== undefined;\n  return (\n    <article className=\"grid min-w-0 gap-5 rounded-2xl bg-card p-4 shadow-sm md:grid-cols-2 md:gap-8 md:p-6\">\n      <div className=\"flex min-w-0 flex-col gap-5\">\n      <header className=\"flex flex-col gap-1\">\n        <h4 className=\"text-title-lg text-foreground\">{binding.device.name}</h4>\n        <p className=\"text-body-md text-muted-foreground\">\n          <span className=\"font-medium text-foreground\">{title}.</span> {note}\n        </p>\n      </header>\n\n      <div className=\"grid grid-cols-[minmax(0,1fr)_auto_minmax(0,1fr)] items-stretch gap-2 sm:gap-3\">\n        <dl className=\"m-0 flex min-w-0 flex-col gap-1 rounded-xl bg-muted/60 p-3 sm:p-4\">\n          <dt className=\"flex items-center gap-1.5 text-label-md text-muted-foreground\">\n            <StateGlyph state=\"confirmed\" size={14} className=\"text-success\" />\n            Device reports\n          </dt>\n          <dd data-testid={`confirmed-${binding.device.id}`} className=\"m-0 break-words text-headline-md text-foreground\">\n            {format(confirmed)}\n          </dd>\n          <dd className=\"m-0 text-label-md text-muted-foreground\">Confirmed</dd>\n        </dl>\n        <span aria-hidden=\"true\" className=\"flex items-center text-muted-foreground rtl:-scale-x-100\">\n          <svg viewBox=\"0 0 24 24\" width={20} height={20} fill=\"none\" stroke=\"currentColor\" strokeWidth={2} strokeLinecap=\"round\" strokeLinejoin=\"round\" focusable=\"false\">\n            <path d=\"M5 12h14m-6-6 6 6-6 6\" />\n          </svg>\n        </span>\n        <dl\n          className={cn(\n            \"m-0 flex min-w-0 flex-col gap-1 rounded-xl border-2 p-3 transition-colors duration-fast motion-reduce:transition-none sm:p-4\",\n            asked ? \"border-dashed border-primary bg-primary/10\" : \"border-transparent bg-muted/30\",\n          )}\n        >\n          <dt className=\"flex items-center gap-1.5 text-label-md text-muted-foreground\">\n            <StateGlyph state={asked ? \"pending\" : \"offline\"} size={14} className={asked ? \"text-primary\" : \"text-muted-foreground\"} />\n            You asked for\n          </dt>\n          <dd data-testid={`requested-${binding.device.id}`} className={cn(\"m-0 break-words\", asked ? \"text-headline-md text-foreground\" : \"text-title-md text-muted-foreground\")}>\n            {asked ? format(requested) : \"Nothing pending\"}\n          </dd>\n          <dd className=\"m-0 text-label-md text-muted-foreground\">{asked ? \"Requested\" : \"No open request\"}</dd>\n        </dl>\n      </div>\n\n      <div className=\"flex min-h-6 items-center\">\n        {stage ? <StateBadge state={stage.state}>{stage.word}</StateBadge> : <StateBadge state=\"confirmed\">Nothing waiting on the device</StateBadge>}\n      </div>\n\n      </div>\n\n      <div className=\"flex min-w-0 flex-col gap-4 md:justify-center\">\n        <div className=\"flex min-w-0 flex-col gap-4 rounded-xl bg-muted/60 p-4\">{children}</div>\n        {command && binding.unsettled ? <CommandLifecycle lifecycle={command.lifecycle} formatValue={format} onRetry={binding.retry} onCancel={binding.cancel} /> : null}\n      </div>\n    </article>\n  );\n}\n\nexport function StateHonestyExample() {\n  const iot = useIotSimulation(agritech, { intervalMs: 500 });\n  const valve02 = controlOf(iot, \"valve-02\", \"position\");\n  const valve03 = controlOf(iot, \"valve-03\", \"position\");\n  const pump = controlOf(iot, \"pump-01\", \"power\");\n  const pumpGone = !iot.sim.devices[\"pump-01\"]!.reachable;\n  const pumpBusy = pump.command ? isLifecyclePending(pump.command.lifecycle) : false;\n\n  return (\n    <section aria-label=\"State honesty demo\" className=\"flex flex-col gap-5\">\n      <SimNotice scenario={agritech}>\n        <SimTransport iot={iot} />\n      </SimNotice>\n\n      <div className=\"flex flex-col gap-4\">\n        {([[\"Reliable valve\", \"Acknowledges, then confirms.\", valve02], [\"Flaky valve\", \"Fails once, then works. Retry is offered, never done for you.\", valve03]] as const).map(\n          ([title, note, valve]) => (\n            <Panel key={valve.device.id} title={title} note={note} binding={valve}>\n              <DeviceModeControl\n                modes={valve.capability.modes ?? []}\n                value={valve.confirmed as string}\n                requested={valve.requested as string | undefined}\n                control={valve.control}\n                label={`${valve.device.name} position`}\n                onSelect={valve.send}\n              />\n            </Panel>\n          ),\n        )}\n\n        <Panel title=\"Unreachable device\" note=\"Send a request, then lose the pump: it times out, then is called unreachable.\" binding={pump}>\n          <DevicePowerControl\n            state={pump.confirmed as \"on\" | \"off\"}\n            requested={pump.requested as \"on\" | \"off\" | undefined}\n            control={pump.control}\n            label={`${pump.device.name} power`}\n            onToggle={pump.send}\n          />\n          <div className=\"flex flex-wrap gap-2\">\n            <button\n              type=\"button\"\n              className={BUTTON}\n              disabled={pumpGone || pumpBusy}\n              onClick={() => {\n                pump.send(pump.confirmed === \"on\" ? \"off\" : \"on\");\n                iot.setReachable(\"pump-01\", false);\n              }}\n            >\n              Request a change, then lose the pump\n            </button>\n            <button type=\"button\" className={BUTTON} disabled={!pumpGone} onClick={() => iot.setReachable(\"pump-01\", true)}>\n              Pump answers again\n            </button>\n          </div>\n        </Panel>\n      </div>\n\n      <p className=\"text-body-md text-muted-foreground\">\n        An optimistic interface would already show the new value the moment you pressed. Here the confirmed value never moves until the device\n        confirms it, so a lock, a valve or a pump is never shown in a state it has not reported.\n      </p>\n    </section>\n  );\n}",
  "smart-space-environment": "/**\n * Connected Space: one home as a place, not a list. A plan of the house with the devices where they are, a\n * room rail with health rolled up from its devices, real controls for whichever room or device you pick, and\n * a side of attention, energy, activity and scenes. Built from one simulated scenario through selectors, so\n * nothing here is a hand-typed count.\n *\n * The aside is ranked, not stacked. Open alerts are always there, expanded, at every width — that is what the\n * column is for. Everything below them is grouped: what is already acknowledged, what happened earlier in the\n * day, and the routines that run themselves each sit behind a group that says what it holds and how many,\n * counted from the data. Nothing is dropped; it is one press away.\n *\n * State stays honest everywhere: the big number, the switch and the marker on the plan show what the device\n * last CONFIRMED. A request is drawn beside it as a dashed \"requested, not yet confirmed\" mark, and a failed\n * or unreachable one keeps the last confirmed value and offers Retry (never automatic).\n *\n * On a phone the header is ranked rather than laid out flat. PRIMARY is where you are and what needs you:\n * the house mark, the home's name, and ONE summary status line (\"7 of 9 online · 3 need attention\")\n * carried by a glyph and words, followed immediately by the floor/room navigation, which is what a phone\n * visitor is actually here to press. SECONDARY is the metadata that explains it: the fabricated address and\n * the simulated clock, quieter and on their own line, wrapping rather than truncating. TERTIARY — energy,\n * activity, scenes — is already behind disclosures in the aside. Nothing truthful is hidden: warnings, stale\n * readings, offline devices, open alerts, requested values and Retry stay where they were.\n *\n * SIMULATED. No device is contacted and nothing is sent over a network. The camera shows a labelled sample\n * frame, never video. Scenes and routines are shown, not executed: KinetixUI has no automation engine.\n */\nconst DAY_MS = 86_400_000;\nconst HOME = \"home\";\n/** Fabricated, and said so. Metadata, not identity: it is quiet, it wraps, and it is never ellipsised. */\nconst HOME_ADDRESS = \"12 Example Lane, Sample City (fabricated)\";\n/** How many of a day's events the aside shows before the rest are grouped behind their real count. */\nconst ACTIVITY_HEAD = 3;\n/**\n * A group nested inside a panel or another disclosure: the same control, one tonal step quieter, so the\n * outer surface stays the card and the group reads as part of it rather than as a second card.\n */\nconst SUBGROUP = \"bg-muted/40 shadow-none\";\n\ntype IconName = \"home\" | \"bell\" | \"flame\" | \"leaf\" | \"power\" | \"lock\" | \"unlock\";\n\n/** Small original glyphs for the rail, the header and the mode tiles. Decorative: the words carry the meaning. */\nfunction Glyph({ name, size = 20 }: { name: IconName; size?: number }) {\n  const d: Record<IconName, React.ReactNode> = {\n    home: <path d=\"M4 11 12 4l8 7M6 10v9h12v-9M10 19v-5h4v5\" />,\n    bell: <path d=\"M6 16V11a6 6 0 0 1 12 0v5l1.5 2h-15ZM10 21h4\" />,\n    flame: <path d=\"M12 3c1 3 5 5 5 10a5 5 0 0 1-10 0c0-2 1-3 2-4 0 2 1 3 2 3 0-3-1-6 1-9Z\" />,\n    leaf: <path d=\"M5 19c0-9 5-14 14-14 0 9-5 14-14 14ZM5 19l7-7\" />,\n    power: <path d=\"M12 3v8M7 6.5a7 7 0 1 0 10 0\" />,\n    lock: <path d=\"M6 11h12v9H6ZM8.5 11V8a3.5 3.5 0 0 1 7 0v3\" />,\n    unlock: <path d=\"M6 11h12v9H6ZM8.5 11V8a3.5 3.5 0 0 1 6.6-1.6\" />,\n  };\n  return (\n    <svg viewBox=\"0 0 24 24\" width={size} height={size} fill=\"none\" stroke=\"currentColor\" strokeWidth={2} strokeLinecap=\"round\" strokeLinejoin=\"round\" aria-hidden=\"true\" focusable=\"false\">\n      {d[name]}\n    </svg>\n  );\n}\n\n/**\n * Mode tiles get as many columns as fit at their minimum, in `rem`, so at 200% text they wrap instead of\n * truncating \"Heat\" to \"Hea\" inside a fixed three-column grid.\n */\nconst TILE_COLUMNS: React.CSSProperties = { gridTemplateColumns: \"repeat(auto-fit, minmax(min(100%, 3.5rem), 1fr))\" };\n\nconst MODE_ICONS: Record<string, IconName> = { heat: \"flame\", eco: \"leaf\", off: \"power\", locked: \"lock\", unlocked: \"unlock\" };\nconst withIcons = (modes: readonly { id: string; label: string }[]) => modes.map((m) => ({ ...m, icon: MODE_ICONS[m.id] ? <Glyph name={MODE_ICONS[m.id]!} size={22} /> : undefined }));\n\n/** The lifecycle of a request that has not landed, or did not. Nothing for a confirmed one. */\nfunction Lifecycle({ binding }: { binding: ControlBinding }) {\n  if (!binding.command || !binding.unsettled) return null;\n  return <CommandLifecycle lifecycle={binding.command.lifecycle} formatValue={binding.format} onRetry={binding.retry} onCancel={binding.cancel} className=\"w-full\" />;\n}\n\n/** A worded battery row: the caption says what the meter is. Nothing when the device has no battery. */\nfunction Battery({ value, name }: { value: number | undefined; name: string }) {\n  if (value === undefined) return null;\n  // Wraps below the narrowest phones: the label and the pill together exceed the content width at 320,\n  // and the pill cannot shrink past its numeral, meter and word.\n  return (\n    <div className=\"flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1 self-start\">\n      <span className=\"text-body-md text-muted-foreground\">Battery</span>\n      <BatteryIndicator value={value} presentation=\"pill\" label={`${name} battery`} />\n    </div>\n  );\n}\n\nconst shown = (value: unknown) => String(value);\nconst onOff = (value: unknown) => (value === \"on\" ? \"On\" : value === \"off\" ? \"Off\" : \"Unknown\");\n\n/** What the plan, the tiles and the rail need to say about one device, read from the simulation. */\ntype DeviceView = {\n  id: string;\n  device: ReturnType<typeof deviceOf>;\n  category: KinetixDeviceCategory;\n  roomId: string;\n  roomName: string;\n  state: HotspotState;\n  statusWord: string;\n  /** The CONFIRMED value. */\n  value?: string;\n  /** The value asked for and not yet confirmed. */\n  requested?: string;\n  on: boolean;\n  /** A lock's CONFIRMED state, from the same binding as `value`, so the drawing and the word cannot disagree. */\n  locked?: boolean;\n  power?: ControlBinding;\n};\n\nfunction deviceView(iot: UseIotSimulation, id: string): DeviceView {\n  const { sim } = iot;\n  const device = deviceOf(sim, id);\n  const room = sim.scenario.spaces.find((s) => s.kind === \"room\" && s.deviceIds?.includes(id));\n  const caps = sim.scenario.capabilities[id] ?? [];\n  const bind = (cap: string) => (caps.some((c) => c.id === cap) ? controlOf(iot, id, cap) : undefined);\n  const power = bind(\"power\");\n  const level = bind(\"level\");\n  const setpoint = bind(\"setpoint\");\n  const lock = bind(\"lock\");\n  const controls = [power, level, setpoint, bind(\"mode\"), lock].filter((b): b is ControlBinding => !!b);\n\n  let value: string | undefined;\n  let requested: string | undefined;\n  let on = false;\n  let locked: boolean | undefined;\n  if (device.type === \"light\" && power) {\n    on = power.confirmed === \"on\";\n    value = on && level ? `${shown(level.confirmed)}%` : onOff(power.confirmed);\n    requested = power.requested !== undefined ? onOff(power.requested) : level?.requested !== undefined ? `${shown(level.requested)}%` : undefined;\n  } else if (power) {\n    on = power.confirmed === \"on\";\n    value = onOff(power.confirmed);\n    requested = power.requested !== undefined ? onOff(power.requested) : undefined;\n  } else if (setpoint) {\n    // Eco is a running mode too; only Off is off. Heat-only, it drew an Eco thermostat as switched off.\n    const mode = bind(\"mode\")?.confirmed;\n    on = mode !== undefined && mode !== \"off\";\n    value = `${shown(setpoint.confirmed)} °C`;\n    requested = setpoint.requested !== undefined ? `${shown(setpoint.requested)} °C` : undefined;\n  } else if (lock) {\n    value = lock.format(lock.confirmed);\n    locked = lock.confirmed === \"locked\" ? true : lock.confirmed === \"unlocked\" ? false : undefined;\n    requested = lock.requested !== undefined ? lock.format(lock.requested) : undefined;\n  } else {\n    const sensor = sim.scenario.sensors.find((s) => s.deviceId === id && (s.metric === \"air-quality\" || s.metric === \"temperature\"));\n    const reading = sensor ? selectReading(sim, id, sensor.metric) : undefined;\n    if (sensor && reading) value = sensor.metric === \"air-quality\" ? `AQI ${reading.value.toFixed(0)}` : `${reading.value.toFixed(1)} ${sensor.unit ?? \"\"}`.trim();\n  }\n\n  const reading = sim.scenario.sensors.filter((s) => s.deviceId === id).map((s) => selectReading(sim, id, s.metric)?.evaluation.state);\n  const alerted = selectAlerts(sim).some((a) => a.deviceId === id);\n  let state: HotspotState = \"confirmed\";\n  let statusWord = \"Online\";\n  if (device.status === \"offline\") [state, statusWord] = [\"offline\", \"Offline\"];\n  else if (controls.some((b) => b.control.availability === \"pending\")) [state, statusWord] = [\"pending\", \"Waiting for the device\"];\n  else if (controls.some((b) => b.unsettled)) [state, statusWord] = [\"warning\", \"Request did not land\"];\n  else if (device.status === \"stale\" || reading.some((r) => r === \"stale\" || r === \"warning\" || r === \"critical\") || alerted) [state, statusWord] = [\"warning\", device.status === \"stale\" ? \"Stale\" : \"Needs attention\"];\n  return { id, device, category: resolveDeviceCategory(device), roomId: room?.id ?? HOME, roomName: room?.name ?? \"Home\", state, statusWord, value, requested, on, locked, power };\n}\n\n/** Temperature and humidity readings for the devices in a room, as words. `stale` is said, not implied. */\nfunction ambientOf(iot: UseIotSimulation, roomId: string) {\n  const ids = iot.sim.scenario.spaces.find((s) => s.id === roomId)?.deviceIds ?? [];\n  const read = (metric: string) => {\n    for (const id of ids) {\n      const sensor = iot.sim.scenario.sensors.find((s) => s.deviceId === id && s.metric === metric);\n      const reading = sensor ? selectReading(iot.sim, id, metric) : undefined;\n      if (sensor && reading) {\n        const text = `${reading.value.toFixed(sensor.decimals ?? 1)} ${sensor.unit ?? \"\"}`.trim();\n        return { text: reading.evaluation.state === \"stale\" ? `${text} · stale` : text, source: deviceOf(iot.sim, id).name };\n      }\n    }\n    return undefined;\n  };\n  return { temperature: read(\"temperature\"), humidity: read(\"humidity\") };\n}\n\n/**\n * A floor and its rooms inside the rail.\n *\n * Same structure as the kit's `RailGroup` — a labelled nested list — with one difference that only applies\n * below `sm`: one room per row. A two-column grid at 326px leaves about 50px for the room name, which both\n * clips the name and leaves a dead cell beside a floor with an odd number of rooms. One column per room is\n * shorter in total (nothing wraps to three lines), leaves the temperature and the warning glyph room to sit\n * on the name's line, and reads as a list you scan rather than a ragged grid. From `sm` the kit's own\n * three-column grid and `lg` single-column rail are unchanged.\n */\nfunction FloorGroup({ label, children }: { label: string; children: React.ReactNode }) {\n  const id = React.useId();\n  return (\n    <li className=\"flex flex-col gap-2 lg:gap-1\">\n      <p id={id} className=\"px-1 text-label-md uppercase tracking-wide text-muted-foreground\">\n        {label}\n      </p>\n      <ul aria-labelledby={id} className=\"flex flex-col gap-2 sm:grid sm:grid-cols-3 lg:flex lg:flex-col lg:gap-1\">\n        {children}\n      </ul>\n    </li>\n  );\n}\n\n/**\n * `break-words` is inherited, so it reaches the rail item's own name span: a room name wider than its column\n * breaks instead of spilling past the tile. Below `sm` — where the rail is the first thing a phone visitor\n * reaches and the room tiles are full-width rows — the selected room also takes an inset ring, because a 10%\n * tint alone is not an obvious selection at arm's length. From `sm` the rail is exactly as it was.\n */\nconst railItemClass = (selected: boolean) => (selected ? \"break-words ring-2 ring-inset ring-primary sm:ring-0\" : \"break-words\");\n\nconst rollupWords = (r: { total: number; offline: number; warning: number; critical: number }) => {\n  const parts = [r.critical ? `${r.critical} critical` : \"\", r.warning ? `${r.warning} needs attention` : \"\", r.offline ? `${r.offline} offline` : \"\"].filter(Boolean);\n  return parts.length ? parts.join(\", \") : \"All devices well\";\n};\n\n/* ---------------------------------- focus compositions ---------------------------------- */\n\n/** The thermostat as the room's hero: a ring around the confirmed target, a request drawn dashed, mode tiles beneath. */\nfunction ClimateHero({ iot, id, roomName }: { iot: UseIotSimulation; id: string; roomName: string }) {\n  const target = controlOf(iot, id, \"setpoint\");\n  const mode = controlOf(iot, id, \"mode\");\n  const battery = target.device.battery;\n  return (\n    <Panel title={target.device.name} description={statusLineOf(target, mode)} as=\"h5\" data-device={id}>\n      <div className=\"grid min-w-0 items-center gap-6 md:grid-cols-2\">\n        <DeviceSetpointControl\n          presentation=\"ring\"\n          current={readingOf(iot, id, \"temperature\").value}\n          target={target.confirmed as number}\n          requestedTarget={target.requested as number | undefined}\n          min={target.capability.min ?? 16}\n          max={target.capability.max ?? 26}\n          step={target.capability.step ?? 0.5}\n          unit=\"°C\"\n          secondary={`${roomName} · ${mode.format(mode.confirmed)} mode`}\n          control={target.control}\n          label={`${target.device.name} target`}\n          onCommit={target.send}\n        />\n        <div className=\"flex min-w-0 flex-col gap-4\">\n          <DeviceModeControl\n            presentation=\"tiles\"\n            modes={withIcons(mode.capability.modes ?? [])}\n            value={mode.confirmed as string}\n            requested={mode.requested as string | undefined}\n            control={mode.control}\n            label={`${target.device.name} mode`}\n            onSelect={mode.send}\n            style={TILE_COLUMNS}\n          />\n          <Battery value={battery} name={target.device.name} />\n        </div>\n      </div>\n      <Lifecycle binding={target} />\n      <Lifecycle binding={mode} />\n    </Panel>\n  );\n}\n\n/** A light: the object, a big switch, and a fat brightness pill. An offline lamp says so and keeps its last settings. */\nfunction LightPanel({ iot, id }: { iot: UseIotSimulation; id: string }) {\n  const power = controlOf(iot, id, \"power\");\n  const level = controlOf(iot, id, \"level\");\n  const offline = power.device.status === \"offline\";\n  return (\n    <Panel title={power.device.name} description={statusLineOf(power, level)} as=\"h5\" data-device={id} className={offline ? \"border-2 border-dashed border-border\" : undefined}>\n      <div className=\"flex min-w-0 items-center gap-4\">\n        <span className=\"shrink-0 rounded-2xl bg-muted/60 p-2\">\n          <DeviceIllustration category=\"light\" on={power.confirmed === \"on\" && !offline} size=\"lg\" />\n        </span>\n        <div className=\"flex min-w-0 flex-col gap-2\">\n          <p className=\"text-headline-lg tabular-nums text-foreground\">{power.confirmed === \"on\" ? `${shown(level.confirmed)}%` : \"Off\"}</p>\n          <DevicePowerControl\n            size=\"lg\"\n            state={power.confirmed as \"on\" | \"off\"}\n            requested={power.requested as \"on\" | \"off\" | undefined}\n            control={power.control}\n            label={`${power.device.name} power`}\n            onToggle={power.send}\n          />\n        </div>\n      </div>\n      <DeviceLevelControl variant=\"pill\" size=\"lg\" value={level.confirmed as number} target={level.requested as number | undefined} unit=\"%\" step={5} control={level.control} label={`${power.device.name} brightness`} onCommit={level.send} />\n      <Lifecycle binding={power} />\n      <Lifecycle binding={level} />\n    </Panel>\n  );\n}\n\n/** A switched plug: one tile, the confirmed state big, the request dashed. */\nfunction PlugTile({ iot, id }: { iot: UseIotSimulation; id: string }) {\n  const power = controlOf(iot, id, \"power\");\n  return (\n    <div className=\"flex min-w-0 flex-col gap-3\" data-device={id}>\n      <Tile\n        name={power.device.name}\n        state={statusLineOf(power)}\n        visual={<DeviceIllustration category=\"plug\" on={power.confirmed === \"on\"} />}\n        value={onOff(power.confirmed)}\n        requested={power.requested !== undefined}\n        requestedWord={`Requested ${onOff(power.requested)}, not yet confirmed`}\n        control={<DevicePowerControl size=\"lg\" state={power.confirmed as \"on\" | \"off\"} requested={power.requested as \"on\" | \"off\" | undefined} control={power.control} label={`${power.device.name} power`} showLabel={false} onToggle={power.send} />}\n      />\n      <Lifecycle binding={power} />\n    </div>\n  );\n}\n\n/**\n * The door: the lock itself, the confirmed word, and locked or unlocked as icon tiles. The lock is slow on purpose,\n * so the gap between asking and locked is visible — and the bolt in the drawing moves when the device CONFIRMS,\n * like the word, never on the request. Word, tile, bolt and the radio's checked state all read `lock.confirmed`.\n */\nfunction LockPanel({ iot, id }: { iot: UseIotSimulation; id: string }) {\n  const lock = controlOf(iot, id, \"lock\");\n  const locked = lock.confirmed === \"locked\" ? true : lock.confirmed === \"unlocked\" ? false : undefined;\n  return (\n    <Panel title={lock.device.name} description={statusLineOf(lock)} as=\"h5\" data-device={id}>\n      <div className=\"flex min-w-0 items-center gap-4\">\n        <span className=\"shrink-0 rounded-2xl bg-muted/60 p-2\">\n          <DeviceIllustration category=\"lock\" locked={locked} size=\"lg\" />\n        </span>\n        <div className=\"flex min-w-0 flex-wrap items-center gap-x-4 gap-y-2\">\n          <p className=\"text-headline-lg text-foreground\">{lock.format(lock.confirmed)}</p>\n          <Battery value={lock.device.battery} name={lock.device.name} />\n        </div>\n      </div>\n      <DeviceModeControl presentation=\"tiles\" modes={withIcons(lock.capability.modes ?? [])} value={lock.confirmed as string} requested={lock.requested as string | undefined} control={lock.control} label=\"Front door lock\" onSelect={lock.send} style={TILE_COLUMNS} />\n      <Lifecycle binding={lock} />\n    </Panel>\n  );\n}\n\nfunction ReadingsPanel({ iot, id, title, metrics }: { iot: UseIotSimulation; id: string; title: string; metrics: { metric: string; label: string }[] }) {\n  const device = deviceOf(iot.sim, id);\n  return (\n    <Panel title={title} description={device.name} as=\"h5\" data-device={id}>\n      <TelemetryGrid label={`${device.name} readings`}>\n        {metrics.map((m) => (\n          <TelemetryMetric key={m.metric} {...readingOf(iot, id, m.metric)} label={m.label} />\n        ))}\n      </TelemetryGrid>\n      <Battery value={device.battery} name={device.name} />\n    </Panel>\n  );\n}\n\nfunction DevicePanel({ iot, id, roomName }: { iot: UseIotSimulation; id: string; roomName: string }) {\n  const device = deviceOf(iot.sim, id);\n  switch (device.type) {\n    case \"thermostat\":\n      return <ClimateHero iot={iot} id={id} roomName={roomName} />;\n    case \"light\":\n      return <LightPanel iot={iot} id={id} />;\n    case \"plug\":\n      return <PlugTile iot={iot} id={id} />;\n    case \"lock\":\n      return <LockPanel iot={iot} id={id} />;\n    case \"air-quality\":\n      return (\n        <ReadingsPanel\n          iot={iot}\n          id={id}\n          title={`Air · ${roomName}`}\n          metrics={[\n            { metric: \"air-quality\", label: \"Air quality\" },\n            { metric: \"temperature\", label: \"Temperature\" },\n            { metric: \"humidity\", label: \"Humidity\" },\n          ]}\n        />\n      );\n    case \"camera\":\n      return (\n        <div className=\"min-w-0\" data-device={id}>\n          <CameraDeviceCard device={device} scene=\"entrance\" posterLabel={SAMPLE_IMAGE_LABEL} privacy=\"off\" now={iot.sim.now} />\n        </div>\n      );\n    default:\n      return <ReadingsPanel iot={iot} id={id} title={`Sensor · ${roomName}`} metrics={[{ metric: \"temperature\", label: \"Temperature\" }]} />;\n  }\n}\n\n/* ---------------------------------- the composition ---------------------------------- */\n\nexport function SmartSpaceEnvironmentExample() {\n  const iot = useIotSimulation(smartSpace, { intervalMs: 1000 });\n  const { sim } = iot;\n  const [spaceId, setSpaceId] = React.useState(\"room-hall\");\n  const [deviceId, setDeviceId] = React.useState<string | null>(null);\n  const [enabled, setEnabled] = React.useState<Record<string, boolean>>({});\n  const days = React.useMemo(() => Array.from({ length: 7 }, (_, i) => new Date(Date.parse(sim.startAt) - (6 - i) * DAY_MS).toISOString().slice(0, 10)), [sim.startAt]);\n  const [day, setDay] = React.useState(days[6]!);\n\n  const spaces = sim.scenario.spaces;\n  const rollups = selectSpaceRollups(sim);\n  const floors = spaces.filter((s) => s.kind === \"floor\");\n  const room = spaces.find((s) => s.id === spaceId && s.kind === \"room\");\n  const allViews = Object.keys(sim.devices).map((id) => deviceView(iot, id));\n  // Open alerts are the point of the aside and are never folded away. Ones already acknowledged are kept —\n  // nothing is dropped — but grouped behind a count, so a handled alert stops competing with an open one.\n  const openAlerts = selectAlerts(sim);\n  const alerts = selectAlerts(sim, { includeAcknowledged: true });\n  const handledAlerts = alerts.filter((a) => !openAlerts.some((open) => open.id === a.id));\n  const needAttention = openAlerts.length;\n  const online = allViews.filter((v) => v.device.status === \"online\").length;\n  const clock = `${sim.now.slice(11, 16)} UTC`;\n\n  const selectRoom = (id: string) => {\n    setSpaceId(id);\n    setDeviceId(null);\n  };\n  const selectDevice = (id: string) => {\n    const view = allViews.find((v) => v.id === id);\n    if (!view) return;\n    setSpaceId(view.roomId);\n    setDeviceId(id);\n  };\n  const jumpToAlerts = () => {\n    const el = document.getElementById(\"space-alerts\");\n    el?.scrollIntoView({ block: \"start\" });\n    el?.focus({ preventScroll: true });\n  };\n\n  const hotspots: PlanHotspot[] = allViews\n    .filter((v) => homeAnchors[v.id])\n    .map((v) => ({ id: v.id, roomId: homeAnchors[v.id]!.roomId, x: homeAnchors[v.id]!.x, y: homeAnchors[v.id]!.y, category: v.category, state: v.state, label: v.device.name, value: v.value, requested: v.requested }));\n  const ambient: RoomAmbient = Object.fromEntries(\n    spaces\n      .filter((s) => s.kind === \"room\")\n      .map((s) => {\n        const a = ambientOf(iot, s.id);\n        return [s.id, [a.temperature?.text, a.humidity?.text].filter((t): t is string => !!t)];\n      }),\n  );\n\n  // A scene is fired by hand, so it leads; a routine or a schedule fires itself, so it keeps its own group.\n  // Both groups sit under the same \"shown, not executed\" sentence, and the group states its real count.\n  const scenes = sim.automations.filter((a) => a.kind === \"scene\");\n  const selfRunning = sim.automations.filter((a) => a.kind !== \"scene\");\n  const routineCard = (automation: (typeof sim.automations)[number]) => {\n    const on = enabled[automation.id] ?? automation.enabled;\n    return (\n      <RoutineCard\n        key={automation.id}\n        automation={{ ...automation, enabled: on, status: on ? (automation.status === \"disabled\" ? \"idle\" : automation.status) : \"disabled\" }}\n        now={sim.now}\n        onToggleEnabled={(next) => setEnabled((prev) => ({ ...prev, [automation.id]: next }))}\n      />\n    );\n  };\n\n  const energy = selectEnergy(sim);\n  const dayLabels = energy ? [...energy.week.map((_, i) => new Date(Date.parse(sim.startAt) - (energy.week.length - i) * DAY_MS).toLocaleDateString(\"en\", { weekday: \"short\", timeZone: \"UTC\" })), \"Today\"] : [];\n  const activity = selectActivity(sim).map((e) => ({ e, date: new Date(e.timestamp).toISOString().slice(0, 10) }));\n  const dayEvents = activity.filter((a) => a.date === day).map((a) => a.e);\n  const stripDays = days.map((date) => ({ id: date, date, count: activity.filter((a) => a.date === date).length }));\n  // The timeline is newest first, so the head is what happened last. The tail is kept, behind its real count.\n  const latestEvents = dayEvents.slice(0, ACTIVITY_HEAD);\n  const earlierEvents = dayEvents.slice(ACTIVITY_HEAD);\n\n  const roomDevices = room?.deviceIds ?? [];\n  const chosen = deviceId && roomDevices.includes(deviceId) ? deviceId : null;\n  const floorName = spaces.find((s) => s.id === room?.parentId)?.name;\n  const ambientHere = room ? ambientOf(iot, room.id) : undefined;\n  const homeRollup = rollups.get(HOME);\n  const air = readingOf(iot, \"air-living\", \"air-quality\");\n  const airState = selectReading(sim, \"air-living\", \"air-quality\")?.evaluation.state;\n  const airShown: ShowcaseState = airState === \"warning\" ? \"warning\" : airState === \"critical\" ? \"critical\" : \"confirmed\";\n\n  // One summary status line, not two chips racing the title: how much of the home is reachable and how much\n  // of it wants you, in one sentence, with the kit's glyph so the state is never colour alone.\n  const summaryLine = `${online} of ${allViews.length} online · ${needAttention} ${needAttention === 1 ? \"needs\" : \"need\"} attention`;\n\n  const header = (\n    <SpaceHeader\n      eyebrow={`Home · ${floors.length} floors`}\n      title={spaces.find((s) => s.id === HOME)?.name ?? \"Home\"}\n      identity={<HouseMark />}\n      status={needAttention ? \"warning\" : \"confirmed\"}\n      statusWord={<bdi>{summaryLine}</bdi>}\n      chips={\n        // Secondary metadata, one quiet block rather than three pills racing the title: the fabricated address\n        // and the simulated clock. It shares its row with the icon buttons instead of pushing them onto a row\n        // of their own, and it wraps — a truncated address tells you neither the street nor that it is fake.\n        // \"Simulated\" stays in the words: that is a truth claim about the clock, not decoration.\n        <p className=\"flex min-w-0 flex-1 flex-col gap-0.5 text-body-sm text-muted-foreground md:flex-none md:flex-row md:items-center md:gap-2\">\n          <bdi>{HOME_ADDRESS}</bdi>\n          <bdi className=\"tabular-nums\">Simulated clock {clock}</bdi>\n        </p>\n      }\n      actions={\n        <IconCluster label=\"Home\">\n          <IconButton label=\"Show the whole home\" pressed={spaceId === HOME} onClick={() => selectRoom(HOME)}>\n            <Glyph name=\"home\" />\n          </IconButton>\n          <IconButton label=\"Jump to alerts\" badge={needAttention} onClick={jumpToAlerts}>\n            <Glyph name=\"bell\" />\n          </IconButton>\n        </IconCluster>\n      }\n    />\n  );\n\n  const rail = (\n    <RailList aria-label=\"Home and rooms\">\n      <RailItem\n        icon={<Glyph name=\"home\" />}\n        name=\"Whole home\"\n        state={`${online} of ${allViews.length} online`}\n        health={homeRollup && homeRollup.warning + homeRollup.critical > 0 ? \"warning\" : undefined}\n        healthWord={homeRollup ? rollupWords(homeRollup) : undefined}\n        selected={spaceId === HOME}\n        onSelect={() => selectRoom(HOME)}\n        className={railItemClass(spaceId === HOME)}\n      />\n      {floors.map((floor) => (\n        <FloorGroup key={floor.id} label={floor.name}>\n          {spaces\n            .filter((s) => s.parentId === floor.id)\n            .map((r) => {\n              const rollup = rollups.get(r.id)!;\n              const a = ambientOf(iot, r.id);\n              return (\n                <RailItem\n                  key={r.id}\n                  icon={<DeviceIcon category={resolveDeviceCategory(deviceOf(sim, r.deviceIds?.[0] ?? \"\"))} size={20} />}\n                  name={r.name}\n                  state={a.temperature?.text ?? `${rollup.total} ${rollup.total === 1 ? \"device\" : \"devices\"}`}\n                  health={rollup.critical ? \"critical\" : rollup.warning ? \"warning\" : rollup.offline ? \"offline\" : undefined}\n                  healthWord={rollupWords(rollup)}\n                  count={rollup.total}\n                  selected={spaceId === r.id}\n                  onSelect={() => selectRoom(r.id)}\n                  className={railItemClass(spaceId === r.id)}\n                />\n              );\n            })}\n        </FloorGroup>\n      ))}\n    </RailList>\n  );\n\n  const canvas = (\n    <SpaceCanvas\n      plan={homePlan}\n      selectedRoomId={room ? room.id : null}\n      onSelectRoom={selectRoom}\n      hotspots={hotspots}\n      selectedHotspotId={chosen}\n      onSelectHotspot={selectDevice}\n      ambient={ambient}\n      hotspotLabels=\"selected\"\n    />\n  );\n\n  const focus = room ? (\n    <>\n      <div className=\"flex min-w-0 flex-wrap items-end justify-between gap-x-6 gap-y-2 px-1\">\n        <div className=\"flex min-w-0 flex-col\">\n          {floorName ? <p className=\"text-label-md uppercase tracking-wide text-muted-foreground\">{floorName}</p> : null}\n          <h4 className=\"text-headline-lg text-foreground\">{room.name}</h4>\n          <p className=\"text-body-md text-muted-foreground\">\n            <bdi>\n              {roomDevices.length} {roomDevices.length === 1 ? \"device\" : \"devices\"} · {rollupWords(rollups.get(room.id)!)}\n            </bdi>\n          </p>\n        </div>\n        {/* The room's temperature is context for the controls below, not the primary value of the screen, so\n            on a phone it is a reading beside the room name rather than a second display-sized number racing\n            it. From `sm` it keeps the size it had. */}\n        {ambientHere?.temperature ? (\n          <p className=\"flex flex-col items-start sm:items-end\">\n            <span className=\"text-headline-sm tabular-nums text-foreground sm:text-display-sm\">\n              <bdi>{ambientHere.temperature.text}</bdi>\n            </span>\n            <span className=\"text-body-sm text-muted-foreground\">Room temperature · {ambientHere.temperature.source}</span>\n          </p>\n        ) : null}\n      </div>\n      {roomDevices.length > 1 ? (\n        <PillSelector\n          label={`Devices in ${room.name}`}\n          showAll\n          allLabel=\"Whole room\"\n          value={chosen ?? \"all\"}\n          onChange={(id) => setDeviceId(id === \"all\" ? null : id)}\n          options={roomDevices.map((id) => ({ id, label: deviceOf(sim, id).name, icon: <DeviceIcon category={resolveDeviceCategory(deviceOf(sim, id))} size={16} /> }))}\n        />\n      ) : null}\n      <div className=\"grid min-w-0 grid-cols-1 gap-4\">\n        {(chosen ? [chosen] : roomDevices).map((id) => (\n          <DevicePanel key={id} iot={iot} id={id} roomName={room.name} />\n        ))}\n      </div>\n    </>\n  ) : (\n    <>\n      <div className=\"flex min-w-0 flex-col gap-1 px-1\">\n        <p className=\"text-label-md uppercase tracking-wide text-muted-foreground\">Whole home</p>\n        <h4 className=\"text-headline-lg text-foreground\">{spaces.find((s) => s.id === HOME)?.name}</h4>\n      </div>\n      <Panel title=\"At a glance\" as=\"h5\">\n        <div className=\"grid grid-cols-1 gap-6 sm:grid-cols-3\">\n          <Stat size=\"lg\" label=\"Living room\" value={ambientOf(iot, \"room-living\").temperature?.text.split(\" \")[0] ?? \"—\"} unit=\"°C\" />\n          <Stat size=\"lg\" label=\"Air quality\" value={air.value === null ? \"—\" : Math.round(air.value)} unit=\"AQI\" state={airShown} stateWord={airShown === \"confirmed\" ? \"Within range\" : undefined} />\n          <Stat size=\"lg\" label=\"Energy today\" value={energy ? energy.summary.total.toFixed(1) : \"—\"} unit={energy?.summary.unit} />\n        </div>\n      </Panel>\n      <div className=\"grid min-w-0 grid-cols-1 gap-3 sm:grid-cols-2\">\n        {allViews.map((v) => (\n          <Tile\n            key={v.id}\n            name={v.device.name}\n            state={`${v.roomName} · ${v.statusWord}`}\n            value={v.value}\n            requested={v.requested !== undefined}\n            requestedWord={`Requested ${v.requested}, not yet confirmed`}\n            visual={<DeviceIllustration category={v.category} on={v.on && v.state !== \"offline\"} locked={v.locked} size=\"md\" />}\n            onSelect={() => selectDevice(v.id)}\n            control={\n              v.power ? (\n                <DevicePowerControl size=\"sm\" showLabel={false} state={v.power.confirmed as \"on\" | \"off\"} requested={v.power.requested as \"on\" | \"off\" | undefined} control={v.power.control} label={`${v.device.name} power`} onToggle={v.power.send} />\n              ) : undefined\n            }\n          />\n        ))}\n      </div>\n    </>\n  );\n\n  const aside = (\n    <>\n      <Panel id=\"space-alerts\" tabIndex={-1} title=\"Needs attention\" description={needAttention ? <bdi>{needAttention} to review</bdi> : \"All clear\"} as=\"h5\" className=\"scroll-mt-4 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring md:col-span-2 xl:col-span-1\">\n        <AlertList hideSummary alerts={openAlerts} onAcknowledge={(alert) => iot.acknowledgeAlert(alert.id)} now={sim.now} emptyLabel=\"Nothing is open. Acknowledged alerts are below.\" />\n        {handledAlerts.length ? (\n          <Disclosure title=\"Acknowledged\" count={handledAlerts.length} countNoun=\"acknowledged alerts\" defaultOpen={false} className={SUBGROUP}>\n            <AlertList hideSummary alerts={handledAlerts} label=\"Acknowledged alerts\" now={sim.now} />\n          </Disclosure>\n        ) : null}\n      </Panel>\n\n      {energy ? (\n        <Disclosure title=\"Energy\" count={energy.summary.items.length} countNoun=\"devices\">\n          <EnergySummary\n            presentation=\"sparkline\"\n            summary={energy.summary}\n            today={energy.summary.total}\n            days={[...energy.week, energy.summary.total]}\n            dayLabels={dayLabels}\n            dailyBaseline={sim.scenario.energy?.baseline}\n            updatedLabel=\"Simulated. Moves with the demo clock.\"\n          />\n        </Disclosure>\n      ) : null}\n\n      <Disclosure title=\"Activity\" count={dayEvents.length} countNoun=\"events on this day\">\n        <DateStrip label=\"Activity day\" days={stripDays} value={day} onChange={setDay} now={sim.now} />\n        <ActivityTimeline variant=\"blocks\" events={latestEvents} now={sim.now} emptyLabel=\"Nothing happened on this day.\" />\n        {earlierEvents.length ? (\n          <Disclosure title=\"Earlier on this day\" count={earlierEvents.length} countNoun=\"earlier events\" defaultOpen={false} className={SUBGROUP}>\n            <ActivityTimeline variant=\"blocks\" events={earlierEvents} label=\"Earlier activity\" now={sim.now} />\n          </Disclosure>\n        ) : null}\n      </Disclosure>\n\n      <Disclosure title=\"Scenes and routines\" count={sim.automations.length} countNoun=\"scenes and routines\">\n        <p className=\"text-body-sm text-muted-foreground\">Shown, not executed: KinetixUI has no automation engine.</p>\n        {scenes.length ? <div className=\"flex flex-col gap-3\">{scenes.map(routineCard)}</div> : null}\n        {/* \"Runs on its own\" is short enough to sit beside its count and chevron without truncating at 292px. */}\n        {selfRunning.length ? (\n          <Disclosure title=\"Runs on its own\" count={selfRunning.length} countNoun=\"routines and schedules\" defaultOpen={false} className={SUBGROUP}>\n            <div className=\"flex flex-col gap-3\">{selfRunning.map(routineCard)}</div>\n          </Disclosure>\n        ) : null}\n      </Disclosure>\n    </>\n  );\n\n  return (\n    <div className=\"flex min-w-0 flex-col gap-4\">\n      <SimNotice scenario={smartSpace}>\n        <SimTransport iot={iot} />\n      </SimNotice>\n      <ShowcaseShell label=\"Connected space\" railLabel=\"Home and rooms\" canvasLabel=\"Home plan\" focusLabel={room ? room.name : \"Whole home\"} asideLabel=\"Attention, energy, activity and scenes\" header={header} rail={rail} canvas={canvas} focus={focus} aside={aside} />\n    </div>\n  );\n}",
  "agritech-environment": "/**\n * An agronomist's daily view of a farm. The FIELD PLAN is the centre: each zone carries its soil moisture and\n * each valve, pump and sensor is a hotspot with an honest state. Selecting a zone (in the rail, the pills on a\n * phone, or on the plan) brings up its moisture as the big number, the valve that irrigates it, and the\n * greenhouse and weather readings around it. Time series and device health come before lighting-style controls.\n *\n * The selected zone reads as four groups, in the order a phone asks the questions: the CURRENT CONDITION\n * (one hero numeral and its distance from the 28% irrigation threshold, in words), SENSOR ATTENTION (what is\n * wrong with the sensor — a low battery is a battery percentage, never a second moisture reading, so it is\n * set small and labelled as such), HISTORY behind a disclosure, and IRRIGATION (the position the valve\n * reports, then anything requested or failed, then the control).\n *\n * Every number is only as current as its reading: a sensor that stopped reporting keeps its last value, said\n * as \"last known\", and never reads as a fresh measurement. The valve and pump are real controls: a request\n * stays unconfirmed until the device reports, and Irrigation Valve 03 is deliberately flaky. It fails once,\n * shows why, and offers Retry rather than retrying for you.\n *\n * SIMULATED. The irrigation rule and the rain forecast are shown, not executed: KinetixUI has no automation\n * engine and fetches no forecast.\n */\ntype Zone = { id: string; name: string; group: string; sensorId?: string; valveId?: string };\n\nconst ZONES: readonly Zone[] = [\n  { id: \"zone-2\", name: \"Zone 2\", group: \"Greenhouse A\", sensorId: \"soil-03\", valveId: \"valve-02\" },\n  { id: \"zone-3\", name: \"Zone 3\", group: \"Greenhouse A\", sensorId: \"soil-04\", valveId: \"valve-03\" },\n  { id: \"field-orchard\", name: \"Orchard block\", group: \"Open field\", sensorId: \"soil-05\" },\n  { id: \"field-yard\", name: \"Utility yard\", group: \"Pump and weather\" },\n];\n\nconst SOIL_LOW = 28;\n\n/** An abstract original farm mark: hills, crop rows and a low sun. Decorative. */\nfunction FarmMark() {\n  return (\n    <span aria-hidden=\"true\" className=\"flex size-12 shrink-0 items-center justify-center rounded-2xl bg-card shadow-sm sm:size-14\">\n      <svg viewBox=\"0 0 48 48\" width={36} height={36} fill=\"none\" strokeLinecap=\"round\" strokeLinejoin=\"round\">\n        <circle cx=\"34\" cy=\"14\" r=\"4\" className=\"fill-warning/60 stroke-none\" />\n        <path d=\"M4 32C14 22 24 28 30 25C36 22 42 24 44 26V38a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2Z\" className=\"fill-success/15 stroke-success/50\" strokeWidth={2} />\n        <path d=\"M12 40V34M20 40V31M28 40V31M36 40V33\" className=\"stroke-primary\" strokeWidth={2.5} />\n      </svg>\n    </span>\n  );\n}\n\nconst ValveOpenGlyph = () => (\n  <svg viewBox=\"0 0 24 24\" width={22} height={22} fill=\"none\" stroke=\"currentColor\" strokeWidth={2} strokeLinecap=\"round\" strokeLinejoin=\"round\" aria-hidden=\"true\" focusable=\"false\">\n    <path d=\"M12 3.5s6 6.4 6 10.5a6 6 0 0 1-12 0c0-4.1 6-10.5 6-10.5Z\" />\n  </svg>\n);\nconst ValveClosedGlyph = () => (\n  <svg viewBox=\"0 0 24 24\" width={22} height={22} fill=\"none\" stroke=\"currentColor\" strokeWidth={2} strokeLinecap=\"round\" strokeLinejoin=\"round\" aria-hidden=\"true\" focusable=\"false\">\n    <circle cx=\"12\" cy=\"12\" r=\"9\" />\n    <path d=\"M8 12h8\" />\n  </svg>\n);\n\nconst FAILED_STAGES = new Set([\"failed\", \"timed-out\", \"unreachable\"]);\n\n/**\n * The lifecycle of a request that has not landed, or did not.\n *\n * Compact, because the words around it already carry the requested and the confirmed value. A failure\n * is lifted into its own tinted block with a heading, so that at phone width the WHY — the device's own\n * reason, from `describeCommandLifecycle` — is read before the control is pressed again, and Retry sits\n * with it. Nothing retries itself.\n */\nfunction CommandProgress({ binding, failureTitle }: { binding: ControlBinding; failureTitle: string }) {\n  if (!binding.command || !binding.unsettled) return null;\n  const body = (\n    <CommandLifecycle\n      lifecycle={binding.command.lifecycle}\n      formatValue={binding.format}\n      onRetry={binding.retry}\n      onCancel={binding.cancel}\n      density=\"compact\"\n      className=\"w-full\"\n    />\n  );\n  if (!FAILED_STAGES.has(binding.command.lifecycle.stage)) return body;\n  const reason = binding.command.lifecycle.reason;\n  return (\n    <div className=\"flex min-w-0 flex-col gap-2 rounded-xl bg-warning/15 p-3\">\n      {/* The device's own reason, at full contrast: on a phone it was the first thing to become unreadable,\n          and without it the honest \"it went back\" looks like a bug rather than a report. */}\n      <p className=\"flex min-w-0 items-start gap-2 text-title-md text-foreground\">\n        <StateGlyph state=\"warning\" className=\"mt-0.5 text-warning\" />\n        <span>\n          {failureTitle}\n          {reason ? ` — ${reason}` : \"\"}\n        </span>\n      </p>\n      {body}\n    </div>\n  );\n}\n\n/** The request, worded and dashed, beside the confirmed value: never a substitute for it. */\nfunction RequestNotice({ children }: { children: React.ReactNode }) {\n  return (\n    <p className=\"flex min-w-0 items-start gap-2 rounded-xl border-2 border-dashed border-primary p-3 text-body-md text-foreground\">\n      <StateGlyph state=\"pending\" className=\"mt-0.5 text-primary\" />\n      <span>{children}</span>\n    </p>\n  );\n}\n\n/** The confirmed state of a control: the label, then the word the device itself reported. */\nfunction ConfirmedState({ what, word, note }: { what: string; word: string; note?: React.ReactNode }) {\n  return (\n    <div className=\"flex min-w-0 flex-col gap-0.5\">\n      <p className=\"text-label-md uppercase tracking-wide text-muted-foreground\">{what}</p>\n      <p className=\"text-headline-sm text-foreground\">{word}</p>\n      {note}\n    </div>\n  );\n}\n\nconst withUnit = (value: number, unit: string | undefined, precision = 0) => `${value.toFixed(precision)}${unit ? (unit === \"%\" ? \"\" : \" \") + unit : \"\"}`;\n\n/** The latest soil moisture of a sensor, judged against its own threshold and freshness window. */\nfunction moistureOf(iot: UseIotSimulation, deviceId: string) {\n  const reading = readingOf(iot, deviceId, \"soil-moisture\");\n  const state: KinetixReadingState = evaluateReading({\n    value: reading.value,\n    timestamp: reading.timestamp,\n    staleAfterMs: reading.staleAfterMs,\n    thresholds: reading.thresholds,\n    metric: \"soil-moisture\",\n    now: reading.now,\n  }).state;\n  return { reading, state, value: reading.value };\n}\n\n/** A moisture bar with the irrigation threshold marked. Fresh and healthy is green; below the line is warning; old is muted. */\nfunction MoistureBar({ value, state, name }: { value: number | null; state: KinetixReadingState; name: string }) {\n  const known = value !== null && state !== \"unavailable\";\n  const width = known ? Math.min(100, Math.max(0, value)) : 0;\n  const tone = state === \"stale\" || state === \"unavailable\" ? \"bg-muted-foreground/40\" : state === \"normal\" ? \"bg-success\" : \"bg-warning\";\n  const sentence = !known\n    ? `${name}: no reading`\n    : `${name}: ${Math.round(value)}%${state === \"stale\" ? \", last known value\" : \"\"}${state === \"warning\" || state === \"critical\" ? \", below the irrigation threshold\" : \"\"}. Irrigation threshold ${SOIL_LOW}%.`;\n  return (\n    <div role=\"img\" aria-label={sentence} className=\"relative h-2.5 w-full rounded-full bg-muted\">\n      <span className={cn(\"absolute inset-y-0 start-0 rounded-full transition-all duration-base motion-reduce:transition-none\", tone)} style={{ inlineSize: `${width}%` }} />\n      <span aria-hidden=\"true\" className=\"absolute -inset-y-1 w-0.5 rounded-full bg-foreground/70\" style={{ insetInlineStart: `${SOIL_LOW}%` }} />\n    </div>\n  );\n}\n\n/** The reading's relationship to the irrigation threshold, in words rather than only as a tick on a bar. */\nfunction thresholdSentence(value: number | null, state: KinetixReadingState): string {\n  if (value === null || state === \"unavailable\") return `No reading. The irrigation threshold is ${SOIL_LOW}%.`;\n  const diff = Math.round(value) - SOIL_LOW;\n  const relation =\n    diff === 0\n      ? `at the irrigation threshold (${SOIL_LOW}%)`\n      : `${Math.abs(diff)} ${Math.abs(diff) === 1 ? \"point\" : \"points\"} ${diff > 0 ? \"above\" : \"below\"} the irrigation threshold (${SOIL_LOW}%)`;\n  return state === \"stale\" ? `Last known reading, ${relation}.` : `${relation[0]!.toUpperCase()}${relation.slice(1)}.`;\n}\n\nconst moistureWord = (state: KinetixReadingState) =>\n  state === \"stale\" ? \"Last known\" : state === \"unavailable\" ? \"No reading\" : state === \"warning\" || state === \"critical\" ? `Below ${SOIL_LOW}%` : \"Soil moisture\";\n\nexport function AgritechEnvironmentExample() {\n  const iot = useIotSimulation(agritech, { intervalMs: 1000 });\n  const { sim } = iot;\n  const [zoneId, setZoneId] = React.useState(\"zone-3\");\n  const [hotspotId, setHotspotId] = React.useState<string | null>(null);\n  const alertsRef = React.useRef<HTMLDivElement>(null);\n\n  const tree = React.useMemo(() => buildSpaceTree(sim.scenario.spaces), [sim.scenario.spaces]);\n  const zone = ZONES.find((z) => z.id === zoneId)!;\n  const rule = sim.scenario.rules[0]!;\n  const forecast = agritechRainForecast;\n  const alerts = selectAlerts(sim, { includeAcknowledged: true });\n  const openAlerts = alerts.filter((a) => !a.resolvedAt);\n  const alertDevices = new Set(openAlerts.map((a) => a.deviceId));\n\n  const pump = controlOf(iot, \"pump-01\", \"power\");\n  const flow = readingOf(iot, \"pump-01\", \"flow\");\n  const pressure = readingOf(iot, \"pump-01\", \"pressure\");\n  const air = readingOf(iot, \"climate-a\", \"temperature\");\n  const humidity = readingOf(iot, \"climate-a\", \"humidity\");\n  const outside = readingOf(iot, \"weather-01\", \"temperature\");\n  const wind = readingOf(iot, \"weather-01\", \"wind-speed\");\n\n  const selectZone = (id: string) => {\n    setZoneId(id);\n    setHotspotId(null);\n  };\n  const selectHotspot = (id: string) => {\n    setHotspotId(id);\n    const room = fieldAnchors[id]?.roomId;\n    if (ZONES.some((z) => z.id === room)) setZoneId(room!);\n  };\n\n  // ---- the plan: one hotspot per placed device, with its honest state and confirmed value ----\n  const hotspots: PlanHotspot[] = sim.scenario.devices.flatMap((device): PlanHotspot[] => {\n    const at = fieldAnchors[device.id];\n    if (!at) return [];\n    // A zone's soil reading is drawn on the plan as its moisture chip (with its state in words), so its sensor\n    // is not a second marker stacked on the same few pixels.\n    if (device.type === \"soil-sensor\" && at.roomId.startsWith(\"zone-\")) return [];\n    const category = resolveDeviceCategory(device);\n    let value: string | undefined;\n    let requested: string | undefined;\n    let pending = false;\n    let attention = alertDevices.has(device.id) || device.status === \"stale\";\n    if (device.type === \"soil-sensor\") {\n      const m = moistureOf(iot, device.id);\n      if (m.value !== null) value = `${withUnit(m.value, \"%\")}${m.state === \"stale\" ? \" · last known\" : \"\"}`;\n      if (m.state !== \"normal\") attention = true;\n    } else if (device.type === \"valve\") {\n      const valve = controlOf(iot, device.id, \"position\");\n      value = valve.format(valve.confirmed);\n      pending = valve.requested !== undefined;\n      if (pending) requested = valve.format(valve.requested);\n      if (valve.command && valve.unsettled && !pending) attention = true;\n    } else if (device.id === \"pump-01\") {\n      value = `${pump.format(pump.confirmed)}${flow.value !== null ? ` · ${withUnit(flow.value, flow.unit, 0)}` : \"\"}`;\n      pending = pump.requested !== undefined;\n      if (pending) requested = pump.format(pump.requested);\n    } else if (device.id === \"climate-a\") {\n      value = air.value !== null ? withUnit(air.value, air.unit, 1) : undefined;\n    } else if (device.id === \"weather-01\") {\n      value = wind.value !== null ? withUnit(wind.value, wind.unit, 0) : undefined;\n    } else {\n      value = \"Connected\";\n    }\n    const state = device.status === \"offline\" ? \"offline\" : pending ? \"pending\" : attention ? \"warning\" : \"confirmed\";\n    return [{ id: device.id, roomId: at.roomId, x: at.x, y: at.y, category, state, label: device.name, value, requested }];\n  });\n\n  const soil = (id: string) => moistureOf(iot, id);\n  const ambient: RoomAmbient = {\n    \"zone-2\": [soil(\"soil-03\").value !== null ? withUnit(soil(\"soil-03\").value!, \"%\") : \"—\"],\n    \"zone-3\": [soil(\"soil-04\").value !== null ? `${withUnit(soil(\"soil-04\").value!, \"%\")}${soil(\"soil-04\").state === \"warning\" ? \" low\" : \"\"}` : \"—\"],\n    \"field-orchard\": [soil(\"soil-05\").value === null ? \"—\" : soil(\"soil-05\").state === \"stale\" ? `Last ${withUnit(soil(\"soil-05\").value!, \"%\")}` : withUnit(soil(\"soil-05\").value!, \"%\")],\n    \"field-yard\": [pump.confirmed === \"on\" ? \"Pump on\" : \"Pump off\"],\n  };\n\n  // ---- rail rows: zone name, moisture as the big number, a bar under it ----\n  const zoneRow = (z: Zone) => {\n    const ids = descendantDeviceIds(tree, z.id);\n    const devices = ids.map((id) => deviceOf(sim, id));\n    const m = z.sensorId ? soil(z.sensorId) : null;\n    const attention = devices.filter((d) => alertDevices.has(d.id) || d.status !== \"online\").length;\n    const valve = z.valveId ? controlOf(iot, z.valveId, \"position\") : null;\n    const big = m ? (m.value !== null ? withUnit(m.value, \"%\") : \"—\") : flow.value !== null ? withUnit(flow.value, \"\") : \"—\";\n    return (\n      <li key={z.id} className=\"min-w-0\">\n        <DeviceGroupCard\n          variant=\"row\"\n          name={z.name}\n          kind={z.group}\n          deviceCount={devices.length}\n          activeCount={devices.filter((d) => d.status === \"online\").length}\n          attentionCount={attention}\n          category={devices[0] ? resolveDeviceCategory(devices[0]) : undefined}\n          summary={valve ? `Valve ${valve.format(valve.confirmed).toLowerCase()}` : z.id === \"field-yard\" ? `Pump ${pump.confirmed === \"on\" ? \"running\" : \"stopped\"}` : undefined}\n          selected={z.id === zoneId}\n          onSelect={() => selectZone(z.id)}\n          className={z.id === zoneId ? \"ring-2 ring-primary\" : undefined}\n          trailing={\n            <span className={cn(\"flex min-w-16 flex-col items-end text-end\", m?.state === \"stale\" && \"text-muted-foreground\")}>\n              <span className=\"text-headline-sm tabular-nums\">\n                <span className=\"sr-only\">{m ? \"Soil moisture \" : \"Pump flow \"}</span>\n                <bdi>{big}</bdi>\n                {!m && flow.unit ? <span className=\"text-label-md text-muted-foreground\"> {flow.unit}</span> : null}\n              </span>\n              <span className=\"text-label-md text-muted-foreground\">{m ? moistureWord(m.state) : \"Pump flow\"}</span>\n            </span>\n          }\n          rollup={m ? <MoistureBar value={m.value} state={m.state} name={`${z.name} soil moisture`} /> : undefined}\n        />\n      </li>\n    );\n  };\n\n  const sensor = zone.sensorId ? deviceOf(sim, zone.sensorId) : null;\n  const zoneMoisture = zone.sensorId ? soil(zone.sensorId) : null;\n  const valve = zone.valveId ? controlOf(iot, zone.valveId, \"position\") : null;\n  const attentionCount = openAlerts.length;\n\n  const pumpBlock = (large: boolean) => (\n    <Panel\n      title=\"Pump Station\"\n      description={large ? \"Feeds every irrigation zone\" : \"Supplies this zone\"}\n      tone={large ? \"surface\" : \"inset\"}\n    >\n      <div className=\"flex flex-wrap items-center justify-between gap-4\">\n        <div className=\"flex min-w-0 flex-wrap items-center gap-4\">\n          <DeviceIllustration category=\"pump\" on={pump.confirmed === \"on\"} size=\"md\" className={large ? \"sm:size-28\" : undefined} />\n          <ConfirmedState what=\"Pump reports\" word={pump.confirmed === \"on\" ? \"Running\" : \"Stopped\"} />\n        </div>\n        <DevicePowerControl\n          state={pump.confirmed as \"on\" | \"off\"}\n          requested={pump.requested as \"on\" | \"off\" | undefined}\n          control={pump.control}\n          label=\"Pump Station power\"\n          size=\"lg\"\n          onToggle={pump.send}\n        />\n      </div>\n      {pump.requested !== undefined ? (\n        <RequestNotice>\n          Requested: {pump.format(pump.requested)}, not yet confirmed. The pump still reports {pump.confirmed === \"on\" ? \"running\" : \"stopped\"}.\n        </RequestNotice>\n      ) : null}\n      <CommandProgress binding={pump} failureTitle=\"The pump did not change\" />\n      {large ? null : <TelemetryMetric {...flow} label=\"Pump flow\" size=\"md\" quietWhenNormal />}\n    </Panel>\n  );\n\n  // ---- the focus area, in four groups a phone can read in order ----\n  // 1 CURRENT CONDITION: one hero numeral for the zone, and its relationship to the threshold in words.\n  const hero =\n    zoneMoisture && sensor ? (\n      <Panel title={`${zone.name} soil moisture`} description={`${zone.group} · ${sensor.name}`}>\n        <div className=\"flex flex-col gap-4 sm:flex-row sm:items-center sm:gap-8\">\n          <TelemetryMetric {...zoneMoisture.reading} label=\"Soil moisture\" size=\"xl\" className=\"sm:min-w-48\" />\n          <div className=\"flex min-w-0 flex-1 flex-col gap-2\">\n            <MoistureBar value={zoneMoisture.value} state={zoneMoisture.state} name={`${zone.name} soil moisture`} />\n            <p className=\"text-body-md text-foreground\">{thresholdSentence(zoneMoisture.value, zoneMoisture.state)}</p>\n          </div>\n          <DeviceIllustration category=\"soil-sensor\" on={zoneMoisture.state !== \"stale\"} size=\"lg\" className=\"hidden sm:block\" />\n        </div>\n      </Panel>\n    ) : (\n      <Panel title=\"Pump Station\" description=\"Utility yard · what the irrigation runs on\">\n        <div className=\"flex flex-col gap-4 sm:flex-row sm:gap-10\">\n          <TelemetryMetric {...flow} label=\"Pump flow\" size=\"xl\" />\n          <TelemetryMetric {...pressure} label=\"Line pressure\" size=\"md\" quietWhenNormal />\n        </div>\n      </Panel>\n    );\n\n  // 2 ATTENTION: what is wrong with the SENSOR, kept apart from the zone's condition and deliberately\n  // quieter than it — a battery percentage is not a second moisture reading.\n  const batteryLevel = classifyBatteryLevel(sensor?.battery);\n  const batteryAlarm = batteryLevel === \"low\" || batteryLevel === \"critical\";\n  const sensorStale = zoneMoisture?.state === \"stale\";\n  const sensorAttention =\n    sensor && (batteryAlarm || sensorStale) ? (\n      <Panel title=\"Sensor attention\" description={`About ${sensor.name} itself, not about the moisture above`} tone=\"inset\">\n        {batteryAlarm ? (\n          <div className=\"flex min-w-0 flex-col gap-1.5\">\n            <p className=\"flex min-w-0 items-start gap-2 text-body-md text-foreground\">\n              <StateGlyph state=\"warning\" className=\"mt-0.5 text-warning\" />\n              <span>\n                {sensor.name} battery is {batteryLevel === \"critical\" ? \"critical\" : \"low\"}. Plan a battery change.\n              </span>\n            </p>\n            <BatteryIndicator value={sensor.battery} label={`${sensor.name} battery`} className=\"ms-6\" />\n            <p className=\"ms-6 text-body-sm text-muted-foreground\">A battery level, not a soil reading.</p>\n          </div>\n        ) : null}\n        {sensorStale ? (\n          <p className=\"flex min-w-0 items-start gap-2 text-body-md text-foreground\">\n            <StateGlyph state=\"offline\" className=\"mt-0.5 text-muted-foreground\" />\n            <span>\n              {sensor.name} has not reported recently. The figure above is its last known value, not the current soil moisture, so it is not used to judge this block.\n            </span>\n          </p>\n        ) : null}\n      </Panel>\n    ) : null;\n\n  // 4 IRRIGATION: the confirmed position first, then anything in flight or failed, then the control.\n  const irrigation = valve ? (\n    <>\n      <Panel title=\"Irrigation valve\" description={`${valve.device.name} · ${valve.device.locationName ?? zone.name}`}>\n        {/* At 320 the large illustration left too little room and clipped the reported word; it grows from sm up. */}\n        <div className=\"flex min-w-0 flex-wrap items-center gap-4\">\n          <DeviceIllustration category=\"valve\" on={valve.confirmed === \"open\"} size=\"md\" className=\"sm:size-28\" />\n          <ConfirmedState\n            what=\"Valve reports\"\n            word={valve.format(valve.confirmed)}\n            note={valve.device.status === \"offline\" ? <StateBadge state=\"offline\">Last known position</StateBadge> : null}\n          />\n        </div>\n        {valve.requested !== undefined ? (\n          <RequestNotice>\n            Requested: {valve.format(valve.requested)}, not yet confirmed. The valve still reports {valve.format(valve.confirmed).toLowerCase()}.\n          </RequestNotice>\n        ) : null}\n        <CommandProgress binding={valve} failureTitle={`${valve.device.name} did not move`} />\n        <DeviceModeControl\n          presentation=\"tiles\"\n          modes={(valve.capability.modes ?? []).map((m) => ({ ...m, icon: m.id === \"open\" ? <ValveOpenGlyph /> : <ValveClosedGlyph /> }))}\n          value={valve.confirmed as string}\n          requested={valve.requested as string | undefined}\n          control={valve.control}\n          label={`${valve.device.name} position`}\n          onSelect={valve.send}\n        />\n      </Panel>\n      {pumpBlock(false)}\n    </>\n  ) : zone.id === \"field-yard\" ? (\n    pumpBlock(true)\n  ) : (\n    <Panel title=\"Irrigation\" description=\"No valve is registered for this block\">\n      <p className=\"text-body-md text-muted-foreground\">Soil Sensor 05 only reads. There is nothing here to open or close, so the plan and the rail are the way to check on this block.</p>\n    </Panel>\n  );\n\n  const conditions = (\n    <Panel title=\"Conditions\" description=\"Greenhouse A air, and the weather station in the utility yard\">\n      <TelemetryGrid label=\"Conditions\" columns={4}>\n        <TelemetryMetric {...air} label=\"Greenhouse air\" size=\"md\" quietWhenNormal />\n        <TelemetryMetric {...humidity} label=\"Humidity\" size=\"md\" quietWhenNormal />\n        <TelemetryMetric {...outside} label=\"Outside air\" size=\"md\" quietWhenNormal />\n        <TelemetryMetric {...wind} label=\"Wind\" size=\"md\" quietWhenNormal />\n      </TelemetryGrid>\n    </Panel>\n  );\n\n  const trendCard = (deviceId: string, metric: string, label: string, height = 140) => (\n    <TelemetryTrend {...trendOf(iot, deviceId, metric)} label={label} height={height} dataTable staleAfterMs={readingOf(iot, deviceId, metric).staleAfterMs} />\n  );\n\n  const focus = (\n    <>\n      {hero}\n      {sensorAttention}\n      {zone.sensorId ? (\n        <Disclosure title=\"Moisture, 7 days\">{trendCard(zone.sensorId, \"soil-moisture\", `${zone.name} soil moisture, last seven days`, 160)}</Disclosure>\n      ) : (\n        <Disclosure title=\"Pump flow, 24 hours\">{trendCard(\"pump-01\", \"flow\", \"Pump flow, last 24 hours\", 160)}</Disclosure>\n      )}\n      {irrigation}\n      {conditions}\n      <Disclosure title=\"Air and weather\">\n        <div className=\"grid grid-cols-1 gap-6 md:grid-cols-2\">\n          {trendCard(\"climate-a\", \"temperature\", \"Greenhouse air temperature, last 24 hours\")}\n          {trendCard(\"climate-a\", \"humidity\", \"Greenhouse humidity, last 24 hours\")}\n          {trendCard(\"weather-01\", \"temperature\", \"Outside air temperature, last 24 hours\")}\n          {trendCard(\"pump-01\", \"flow\", \"Pump flow, last 24 hours\")}\n        </div>\n      </Disclosure>\n    </>\n  );\n\n  // ---- the aside: attention first, then device health, then the rule, then activity ----\n  const batteryDevices = sim.scenario.devices\n    .filter((d) => d.battery !== undefined || d.status !== \"online\")\n    .map((d) => deviceOf(sim, d.id))\n    .sort((a, b) => Number(a.status === \"online\") - Number(b.status === \"online\") || (a.battery ?? 101) - (b.battery ?? 101));\n\n  const aside = (\n    <>\n      <div ref={alertsRef} tabIndex={-1} id=\"agritech-attention\" className=\"min-w-0 focus-visible:outline-none md:col-span-2 xl:col-span-1\">\n        <Panel title=\"Needs attention\" description={openAlerts.length === 0 ? \"Nothing is waiting on you\" : `${openAlerts.length} open`}>\n          <AlertList\n            alerts={alerts}\n            deviceName={(id) => deviceOf(sim, id).name}\n            onAcknowledge={(alert) => iot.acknowledgeAlert(alert.id)}\n            now={sim.now}\n            label=\"Farm alerts\"\n          />\n        </Panel>\n      </div>\n\n      <Panel title=\"Device health\" description=\"Batteries and reporting, lowest first\">\n        <DeviceHealthSummary summary={selectFleetHealth(sim)} noun={{ one: \"device\", other: \"devices\" }} />\n        <ul aria-label=\"Batteries and reporting\" className=\"m-0 flex list-none flex-col gap-3 p-0\">\n          {batteryDevices.map((d) => (\n            <li key={d.id} className=\"flex min-w-0 items-center gap-3\">\n              <DeviceIllustration category={resolveDeviceCategory(d)} on={d.status === \"online\"} size=\"sm\" className=\"size-8\" />\n              <span className=\"flex min-w-0 flex-1 flex-col\">\n                <span className=\"text-body-md text-foreground\">{d.name}</span>\n                <span className=\"flex flex-wrap items-center gap-x-3 gap-y-1 text-body-sm text-muted-foreground\">\n                  <span>{d.locationName}</span>\n                  {d.battery !== undefined ? <BatteryIndicator value={d.battery} label={`${d.name} battery`} /> : null}\n                  {d.status !== \"online\" ? <StateBadge state=\"offline\" className=\"text-body-sm\">Not reporting</StateBadge> : null}\n                </span>\n              </span>\n            </li>\n          ))}\n        </ul>\n      </Panel>\n\n      <Panel title=\"Irrigation rule\" description=\"Shown, not executed: KinetixUI has no automation engine.\" className=\"md:col-span-2 xl:col-span-1\">\n        <AutomationRuleView rule={rule} labelFor={(_kind, id) => sim.scenario.labels?.[id]} />\n        <div className=\"flex flex-col gap-1 rounded-xl bg-muted/60 p-3\">\n          <p className=\"text-title-sm text-foreground\">\n            Rain forecast: {forecast.expected ? \"expected\" : \"not expected\"} ({forecast.probabilityPct}% chance)\n          </p>\n          <p className=\"text-body-sm text-muted-foreground\">Application-provided demo data — KinetixUI fetches no forecast.</p>\n        </div>\n        <div className=\"flex flex-col gap-3\">\n          {sim.automations.map((automation) => (\n            <RoutineCard key={automation.id} automation={automation} now={sim.now} className=\"bg-muted/40\" />\n          ))}\n        </div>\n      </Panel>\n\n      <Disclosure title=\"Activity\" count={selectActivity(sim, { limit: 6 }).length} countNoun=\"events\" className=\"md:col-span-2 xl:col-span-1\">\n        <ActivityTimeline variant=\"rail\" events={selectActivity(sim, { limit: 6 })} deviceName={(id) => deviceOf(sim, id).name} now={sim.now} />\n      </Disclosure>\n    </>\n  );\n\n  return (\n    <div className=\"flex min-w-0 flex-col gap-4\">\n      <SimNotice scenario={agritech}>\n        <SimTransport iot={iot} />\n      </SimNotice>\n\n      <ShowcaseShell\n        label=\"Demo Farm\"\n        railLabel=\"Fields and zones\"\n        canvasLabel=\"Farm plan\"\n        focusLabel={`${zone.name} detail`}\n        asideLabel=\"Attention, device health and irrigation rule\"\n        header={\n          <SpaceHeader\n            identity={<FarmMark />}\n            eyebrow=\"Farm · 3 fields\"\n            title=\"Demo Farm\"\n            location=\"Greenhouse A, Orchard block, Utility yard\"\n            status={attentionCount > 0 ? \"warning\" : \"confirmed\"}\n            statusWord={attentionCount > 0 ? `${attentionCount} open ${attentionCount === 1 ? \"alert\" : \"alerts\"}` : \"All clear\"}\n            chips={\n              <>\n                <SummaryChip label=\"Air\" value={air.value !== null ? withUnit(air.value, air.unit, 1) : \"—\"} />\n                <SummaryChip label=\"Humidity\" value={humidity.value !== null ? withUnit(humidity.value, humidity.unit) : \"—\"} />\n                <SummaryChip label=\"Rain\" value={`${forecast.probabilityPct}% · demo data`} />\n              </>\n            }\n            attention={\n              <AttentionButton\n                count={attentionCount}\n                label={attentionCount === 1 ? \"needs attention\" : \"need attention\"}\n                onClick={() => {\n                  alertsRef.current?.scrollIntoView({ block: \"start\" });\n                  alertsRef.current?.focus({ preventScroll: true });\n                }}\n              />\n            }\n          />\n        }\n        rail={\n          <div className=\"flex flex-col gap-3\">\n            <p className=\"hidden text-label-md uppercase tracking-wide text-muted-foreground lg:block\">Fields and zones</p>\n            <div className=\"lg:hidden\">\n              <PillSelector label=\"Zone\" options={ZONES.map((z) => ({ id: z.id, label: z.name }))} value={zoneId} onChange={selectZone} />\n            </div>\n            <ul aria-label=\"Zones\" className=\"m-0 hidden list-none flex-col gap-2 p-0 lg:flex\">\n              {ZONES.map(zoneRow)}\n            </ul>\n          </div>\n        }\n        canvas={\n          <SpaceCanvas\n            plan={fieldPlan}\n            selectedRoomId={zoneId}\n            onSelectRoom={(id) => ZONES.some((z) => z.id === id) && selectZone(id)}\n            hotspots={hotspots}\n            selectedHotspotId={hotspotId}\n            onSelectHotspot={selectHotspot}\n            ambient={ambient}\n            hotspotLabels=\"selected\"\n          />\n        }\n        focus={focus}\n        aside={aside}\n      />\n    </div>\n  );\n}",
  "operations-environment": "/**\n * Site 04 as a shift supervisor sees it: fleet health and utilisation on top, an alert queue to triage, the site\n * plan as the map, and one selected machine to inspect and command. Every figure is derived from the simulation\n * (`summarizeFleetHealth`, `rollupSpaceHealth`, confirmed values, readings) rather than typed into the page.\n *\n * State honesty: the big numbers are what the devices last CONFIRMED. A request shows beside them as a dashed,\n * worded \"requested, not yet confirmed\" until the device agrees; an offline meter shows its last reading as stale,\n * never as current. Routines are shown, not executed: KinetixUI has no automation engine.\n *\n * SIMULATED. No device is contacted and nothing is sent over a network.\n */\nconst STALE_AFTER_MS = 15 * 60_000;\nconst DAY_MS = 86_400_000;\n/** The load meter that reports for each line. Application configuration, not something the package knows. */\nconst LINE_METER: Record<string, string> = {\n  \"line-1\": \"e-101\",\n  \"line-2\": \"e-201\",\n  \"line-3\": \"e-301\",\n};\n/** Firmware a product's back end says exists. Application-provided demo data: KinetixUI checks nothing. */\nconst FIRMWARE_AVAILABLE: Record<string, string> = { \"g-01\": \"4.2.0\" };\nconst METRIC_LABEL: Record<string, string> = {\n  vibration: \"Vibration\",\n  temperature: \"Temperature\",\n  pressure: \"Pressure\",\n  power: \"Load\",\n};\n\nconst isMachine = (iot: ReturnType<typeof useIotSimulation>, id: string) =>\n  (iot.sim.scenario.capabilities[id] ?? []).some((c) => c.kind === \"power\");\nconst isDown = (status: string) =>\n  status === \"offline\" || status === \"unreachable\";\nconst isRunning = (iot: ReturnType<typeof useIotSimulation>, id: string) => {\n  const rt = iot.sim.devices[id]!;\n  return rt.confirmedValues.power === \"on\" && !isDown(rt.device.status);\n};\n\n/** The lifecycle of a request that has not landed, or did not. Nothing for a confirmed one. */\nfunction Lifecycle({ binding }: { binding: ControlBinding }) {\n  if (!binding.command || !binding.unsettled) return null;\n  return (\n    <CommandLifecycle\n      lifecycle={binding.command.lifecycle}\n      formatValue={binding.format}\n      onRetry={binding.retry}\n      onCancel={binding.cancel}\n      className=\"w-full\"\n    />\n  );\n}\n\n/** An abstract original plant mark: a saw-tooth roofline over a chimney. Decorative. */\nfunction PlantMark() {\n  return (\n    <span\n      aria-hidden=\"true\"\n      className=\"flex size-12 shrink-0 items-center justify-center rounded-2xl bg-card shadow-sm sm:size-14\"\n    >\n      <svg\n        viewBox=\"0 0 48 48\"\n        width={36}\n        height={36}\n        fill=\"none\"\n        strokeLinecap=\"round\"\n        strokeLinejoin=\"round\"\n      >\n        <path\n          d=\"M8 40V24l10 6V24l10 6V24l10 6v10Z\"\n          className=\"fill-primary/10 stroke-primary\"\n          strokeWidth={2.5}\n        />\n        <path\n          d=\"M36 30V10h5v22\"\n          className=\"fill-card stroke-muted-foreground/50\"\n          strokeWidth={2}\n        />\n        <path\n          d=\"M6 40h38\"\n          className=\"stroke-muted-foreground/50\"\n          strokeWidth={2}\n        />\n        <circle\n          cx=\"36\"\n          cy=\"6\"\n          r=\"2\"\n          className=\"fill-muted-foreground/30 stroke-none\"\n        />\n      </svg>\n    </span>\n  );\n}\n\n/** Line status from its rollup: one word, one glyph, never colour alone. */\nfunction lineStatus(r: {\n  critical: number;\n  warning: number;\n  degraded: number;\n  offline: number;\n}): { state: ShowcaseState; word: string } {\n  if (r.critical > 0) return { state: \"critical\", word: \"Critical\" };\n  if (r.warning > 0 || r.degraded > 0)\n    return { state: \"warning\", word: \"Needs attention\" };\n  if (r.offline > 0) return { state: \"offline\", word: \"Device offline\" };\n  return { state: \"confirmed\", word: \"Running\" };\n}\n\nexport function OperationsEnvironmentExample() {\n  const iot = useIotSimulation(operations, { intervalMs: 1000 });\n  const { sim } = iot;\n  const [lineId, setLineId] = React.useState(\"line-2\");\n  const [deviceId, setDeviceId] = React.useState(\"p-201\");\n  const [enabled, setEnabled] = React.useState<Record<string, boolean>>({});\n  const triageRef = React.useRef<HTMLDivElement>(null);\n\n  const tree = React.useMemo(\n    () => buildSpaceTree(sim.scenario.spaces),\n    [sim.scenario.spaces],\n  );\n  const rollups = selectSpaceRollups(sim);\n  const fleet = selectFleetHealth(sim);\n  const lines = sim.scenario.spaces.filter((space) => space.kind === \"line\");\n  const line = lines.find((l) => l.id === lineId) ?? lines[0]!;\n  const alerts = selectAlerts(sim, { includeAcknowledged: true });\n  const openAlerts = selectAlerts(sim);\n  const energy = selectEnergy(sim);\n  const dayLabels = energy?.week.map((_, i) =>\n    new Date(\n      Date.parse(sim.startAt) - (energy.week.length - i) * DAY_MS,\n    ).toLocaleDateString(\"en\", { weekday: \"short\", timeZone: \"UTC\" }),\n  );\n  const siteRollup = rollups.get(\"site-04\")!;\n\n  // Utilisation: machines whose CONFIRMED power is on, over machines that can be run at all.\n  const machineIds = Object.keys(sim.devices).filter((id) =>\n    isMachine(iot, id),\n  );\n  const running = machineIds.filter((id) => isRunning(iot, id)).length;\n  const siteLoad = readingOf(iot, \"e-301\", \"power\");\n\n  const lineOf = (id: string) => siteAnchors[id]?.roomId ?? lines[0]!.id;\n  const select = (id: string) => {\n    setDeviceId(id);\n    setLineId(lineOf(id));\n  };\n  const chooseLine = (id: string) => {\n    setLineId(id);\n    // Land on the machine that most needs a look: an open alert, else the first device on the line.\n    const ids = descendantDeviceIds(tree, id);\n    const flagged = ids.find(\n      (d) =>\n        openAlerts.some((a) => a.deviceId === d) ||\n        sim.devices[d]!.device.status === \"warning\",\n    );\n    setDeviceId(flagged ?? ids[0]!);\n  };\n\n  const valueOf = (id: string): string | undefined => {\n    if (isMachine(iot, id)) {\n      if (isDown(sim.devices[id]!.device.status)) return undefined;\n      const level = (sim.scenario.capabilities[id] ?? []).find(\n        (c) => c.kind === \"level\",\n      );\n      const confirmed = level\n        ? (sim.devices[id]!.confirmedValues[level.id] as number | undefined)\n        : undefined;\n      return isRunning(iot, id)\n        ? `Running${confirmed !== undefined ? ` ${confirmed}%` : \"\"}`\n        : \"Stopped\";\n    }\n    const sensor = sim.scenario.sensors.find((s) => s.deviceId === id);\n    if (!sensor) return undefined;\n    const reading = readingOf(iot, id, sensor.metric);\n    return reading.value === null\n      ? undefined\n      : `${reading.value.toFixed(sensor.decimals ?? 1)} ${sensor.unit ?? \"\"}`.trim();\n  };\n\n  const requestedOf = (id: string): string | undefined => {\n    const rt = sim.devices[id]!;\n    const cap = (sim.scenario.capabilities[id] ?? []).find(\n      (c) => rt.requestedValues[c.id] !== undefined,\n    );\n    return cap\n      ? controlOf(iot, id, cap.id).format(rt.requestedValues[cap.id])\n      : undefined;\n  };\n\n  // The plan marks machines, the gateway and anything that needs a look; meters and sensors live in the equipment list.\n  const onPlan = (id: string) =>\n    id === deviceId ||\n    isMachine(iot, id) ||\n    deviceOf(sim, id).type === \"gateway\" ||\n    deviceOf(sim, id).status !== \"online\";\n  const hotspots: PlanHotspot[] = Object.keys(siteAnchors)\n    .filter(onPlan)\n    .map((id) => {\n      const device = deviceOf(sim, id);\n      const anchor = siteAnchors[id]!;\n      const requested = requestedOf(id);\n      const state: PlanHotspot[\"state\"] = isDown(device.status)\n        ? \"offline\"\n        : device.status === \"warning\"\n          ? \"warning\"\n          : requested\n            ? \"pending\"\n            : \"confirmed\";\n      return {\n        id,\n        roomId: anchor.roomId,\n        x: anchor.x,\n        y: anchor.y,\n        category: resolveDeviceCategory(device),\n        state,\n        label: device.name,\n        value: valueOf(id),\n        requested,\n      };\n    });\n\n  const device = deviceOf(sim, deviceId);\n  const category = resolveDeviceCategory(device);\n  const caps = sim.scenario.capabilities[deviceId] ?? [];\n  const power = caps.some((c) => c.kind === \"power\")\n    ? controlOf(iot, deviceId, \"power\")\n    : null;\n  const levelCap = caps.find((c) => c.kind === \"level\");\n  const level = levelCap ? controlOf(iot, deviceId, levelCap.id) : null;\n  const down = isDown(device.status);\n  const pending = [power, level].filter(\n    (b): b is ControlBinding => !!b && b.requested !== undefined,\n  );\n  const availableFirmware = FIRMWARE_AVAILABLE[deviceId];\n  const inspectorState: ShowcaseState = down\n    ? \"offline\"\n    : device.status === \"warning\"\n      ? \"warning\"\n      : pending.length\n        ? \"pending\"\n        : \"confirmed\";\n  const lineName = lines.find((l) => l.id === lineOf(deviceId))?.name;\n\n  // Telemetry for the selected device: live sensors first, then any history the device only has as a series.\n  const metrics = [\n    ...new Set([\n      ...sim.scenario.sensors\n        .filter((s) => s.deviceId === deviceId)\n        .map((s) => s.metric),\n      ...sim.scenario.series\n        .filter((s) => s.deviceId === deviceId)\n        .map((s) => s.metric),\n    ]),\n  ];\n  const metricProps = (metric: string) => {\n    const live = readingOf(iot, deviceId, metric);\n    if (live.value !== null) return { ...live, label: METRIC_LABEL[metric] };\n    // No live reading: show the last point of the history, dated, so it reads as stale and not as now.\n    const last = trendOf(iot, deviceId, metric).series.points.at(-1);\n    return {\n      metric,\n      label: METRIC_LABEL[metric],\n      value: last?.value ?? null,\n      unit: last?.unit,\n      timestamp: last?.timestamp,\n      staleAfterMs: STALE_AFTER_MS,\n      now: sim.now,\n    };\n  };\n\n  const lineDevices = descendantDeviceIds(tree, line.id)\n    .map((id) => ({\n      id,\n      device: deviceOf(sim, id),\n      rank: isDown(sim.devices[id]!.device.status)\n        ? 1\n        : sim.devices[id]!.device.status === \"warning\"\n          ? 0\n          : 2,\n    }))\n    .sort((a, b) => a.rank - b.rank);\n  const status = lineStatus(rollups.get(line.id)!);\n  const meter = LINE_METER[line.id]!;\n  const lineLoad = readingOf(iot, meter, \"power\");\n  const lineMachines = descendantDeviceIds(tree, line.id).filter((id) =>\n    isMachine(iot, id),\n  );\n\n  const attentionCount =\n    siteRollup.warning + siteRollup.critical + siteRollup.offline;\n\n  return (\n    <section aria-label=\"Site 04 operations\" className=\"flex flex-col gap-4\">\n      <SimNotice scenario={operations}>\n        <SimTransport iot={iot} />\n      </SimNotice>\n\n      <div className=\"flex min-w-0 flex-col gap-6 rounded-container bg-muted/40 p-4 sm:p-6 lg:gap-8 lg:p-8\">\n        <SpaceHeader\n          identity={<PlantMark />}\n          eyebrow=\"Demo Manufacturing Co · Shift supervisor\"\n          title=\"Site 04\"\n          location=\"3 lines · 24 devices\"\n          status={attentionCount > 0 ? \"warning\" : \"confirmed\"}\n          statusWord={\n            attentionCount > 0\n              ? `${siteRollup.warning + siteRollup.critical} warning · ${siteRollup.offline} offline`\n              : \"All systems running\"\n          }\n          chips={\n            siteLoad.value !== null ? (\n              <SummaryChip\n                label=\"Site load\"\n                value={`${siteLoad.value.toFixed(1)} kW`}\n              />\n            ) : undefined\n          }\n          attention={\n            <AttentionButton\n              count={openAlerts.length}\n              label={\n                openAlerts.length === 1 ? \"alert to triage\" : \"alerts to triage\"\n              }\n              onClick={() => {\n                triageRef.current?.focus();\n                triageRef.current?.scrollIntoView?.({ block: \"nearest\" });\n              }}\n            />\n          }\n        />\n\n        <Panel\n          aria-label=\"Fleet health\"\n          className=\"lg:flex-row lg:items-center lg:justify-between lg:gap-8\"\n        >\n          {/* An overview count, not the primary state of anything: one step below the selected machine. */}\n          <DeviceHealthSummary\n            summary={fleet}\n            noun={{ one: \"device\", other: \"devices\" }}\n            className=\"lg:max-w-2xl lg:flex-1\"\n          />\n          {/* Overview figures, so one step below the selected machine's own reported state. */}\n          <div className=\"grid grid-cols-2 gap-4 lg:flex lg:gap-10\">\n            <Stat\n              size=\"md\"\n              label=\"Utilisation\"\n              value={\n                machineIds.length\n                  ? Math.round((running / machineIds.length) * 100)\n                  : 0\n              }\n              unit=\"%\"\n              trend={`${running} of ${machineIds.length} machines running`}\n            />\n            <Stat\n              size=\"md\"\n              label=\"Site load\"\n              value={\n                siteLoad.value !== null\n                  ? siteLoad.value.toFixed(1)\n                  : \"No reading\"\n              }\n              unit={siteLoad.value !== null ? \"kW\" : undefined}\n              trend=\"Main meter E-301\"\n            />\n          </div>\n        </Panel>\n\n        <div className=\"grid min-w-0 grid-cols-1 gap-6 md:gap-8 lg:grid-cols-12\">\n          {/* Attend first: the queue, then the lines, then the equipment on the selected line. */}\n          <div className=\"flex min-w-0 flex-col gap-4 lg:col-span-4\">\n            <div\n              ref={triageRef}\n              tabIndex={-1}\n              className=\"rounded-2xl focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring\"\n            >\n              <Panel\n                title=\"Alert triage\"\n                description=\"Worst first. Acknowledging keeps the alert on the list.\"\n                action={\n                  <span className=\"text-headline-sm tabular-nums text-foreground\">\n                    {openAlerts.length}\n                    <span className=\"sr-only\"> to acknowledge</span>\n                  </span>\n                }\n              >\n                <AlertList\n                  variant=\"list\"\n                  alerts={alerts}\n                  deviceName={(id) => deviceOf(sim, id).name}\n                  onAcknowledge={(alert) => iot.acknowledgeAlert(alert.id)}\n                  now={sim.now}\n                  label=\"Site 04 alerts\"\n                />\n              </Panel>\n            </div>\n\n            <Panel title=\"Lines\" tone=\"surface\">\n              <RailList aria-label=\"Production lines\" className=\"gap-1\">\n                {lines.map((l) => {\n                  const r = rollups.get(l.id)!;\n                  const s = lineStatus(r);\n                  const ids = descendantDeviceIds(tree, l.id).filter((id) =>\n                    isMachine(iot, id),\n                  );\n                  return (\n                    <RailItem\n                      key={l.id}\n                      name={l.name}\n                      state={`${s.word} · ${ids.filter((id) => isRunning(iot, id)).length}/${ids.length} running`}\n                      health={s.state}\n                      healthWord={s.word}\n                      selected={l.id === line.id}\n                      onSelect={() => chooseLine(l.id)}\n                      icon={\n                        <svg\n                          viewBox=\"0 0 24 24\"\n                          width={18}\n                          height={18}\n                          fill=\"none\"\n                          stroke=\"currentColor\"\n                          strokeWidth={2}\n                          strokeLinecap=\"round\"\n                          strokeLinejoin=\"round\"\n                          focusable=\"false\"\n                        >\n                          <path d=\"M3 18V9l6 4V9l6 4V6h3v12Z\" />\n                        </svg>\n                      }\n                    />\n                  );\n                })}\n              </RailList>\n            </Panel>\n\n            <Disclosure\n              title=\"Equipment\"\n              count={lineDevices.length}\n              countNoun=\"devices\"\n            >\n              <ul\n                aria-label={`Equipment on ${line.name}`}\n                className=\"m-0 flex list-none flex-col divide-y divide-border p-0\"\n              >\n                {lineDevices.map(({ id, device: d }) => {\n                  const s: ShowcaseState = isDown(d.status)\n                    ? \"offline\"\n                    : d.status === \"warning\"\n                      ? \"warning\"\n                      : requestedOf(id)\n                        ? \"pending\"\n                        : \"confirmed\";\n                  const v = valueOf(id);\n                  return (\n                    <li key={id}>\n                      <button\n                        type=\"button\"\n                        aria-current={id === deviceId ? \"true\" : undefined}\n                        onClick={() => select(id)}\n                        className={`flex min-h-11 w-full min-w-0 items-center gap-3 rounded-xl px-2 py-2 text-start transition-colors duration-fast motion-reduce:transition-none focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring ${id === deviceId ? \"bg-primary/10 font-semibold\" : \"hover:bg-muted/60\"}`}\n                      >\n                        <span className=\"flex min-w-0 flex-1 flex-col\">\n                          <span className=\"truncate text-body-md text-foreground\">\n                            {d.name}\n                          </span>\n                          {s !== \"confirmed\" ? (\n                            <span className=\"inline-flex items-center gap-1 text-body-sm font-normal text-muted-foreground\">\n                              <StateGlyph state={s} size={14} />\n                              {s === \"pending\"\n                                ? \"Requested, not confirmed\"\n                                : showcaseStateWord(s)}\n                            </span>\n                          ) : null}\n                        </span>\n                        {v ? (\n                          <bdi className=\"shrink-0 text-body-md font-normal tabular-nums text-muted-foreground\">\n                            {v}\n                          </bdi>\n                        ) : null}\n                      </button>\n                    </li>\n                  );\n                })}\n              </ul>\n            </Disclosure>\n          </div>\n\n          <div className=\"flex min-w-0 flex-col gap-6 md:gap-8 lg:col-span-8\">\n            <Panel\n              title=\"Site plan\"\n              description={`${line.name} is highlighted. Select a machine on the plan.`}\n              aria-label=\"Site plan\"\n              className=\"p-2 sm:p-5\"\n              action={\n                <span className=\"inline-flex items-center gap-1.5 text-body-md text-foreground\">\n                  <StateGlyph\n                    state={status.state}\n                    className={\n                      status.state === \"confirmed\"\n                        ? \"text-success\"\n                        : status.state === \"warning\"\n                          ? \"text-warning\"\n                          : \"text-muted-foreground\"\n                    }\n                  />\n                  {status.word}\n                </span>\n              }\n            >\n              <SpaceCanvas\n                plan={sitePlan}\n                selectedRoomId={line.id}\n                onSelectRoom={chooseLine}\n                hotspots={hotspots}\n                selectedHotspotId={deviceId}\n                onSelectHotspot={select}\n              />\n              <dl className=\"m-0 grid grid-cols-2 gap-4 rounded-xl bg-muted/60 p-4 sm:grid-cols-4\">\n                <div className=\"flex flex-col\">\n                  <dt className=\"text-body-sm text-muted-foreground\">\n                    Running\n                  </dt>\n                  <dd className=\"m-0 text-headline-sm tabular-nums text-foreground\">\n                    {lineMachines.filter((id) => isRunning(iot, id)).length}\n                    <span className=\"text-title-md text-muted-foreground\">\n                      {\" \"}\n                      / {lineMachines.length}\n                    </span>\n                  </dd>\n                </div>\n                <div className=\"flex flex-col\">\n                  <dt className=\"text-body-sm text-muted-foreground\">\n                    Line load\n                  </dt>\n                  <dd className=\"m-0 text-headline-sm tabular-nums text-foreground\">\n                    {lineLoad.value !== null ? (\n                      <>\n                        {lineLoad.value.toFixed(1)}\n                        <span className=\"text-title-md text-muted-foreground\">\n                          {\" \"}\n                          kW\n                        </span>\n                      </>\n                    ) : (\n                      <span className=\"text-title-md text-muted-foreground\">\n                        No reading\n                      </span>\n                    )}\n                  </dd>\n                  {lineLoad.value === null ? (\n                    <dd className=\"m-0 text-body-sm text-muted-foreground\">\n                      {deviceOf(sim, meter).name} is offline\n                    </dd>\n                  ) : null}\n                </div>\n                <div className=\"flex flex-col sm:col-span-2\">\n                  <dt className=\"text-body-sm text-muted-foreground\">Status</dt>\n                  <dd className=\"m-0 text-body-md text-foreground\">\n                    <StateBadge state={status.state}>{status.word}</StateBadge>\n                    <span className=\"block text-body-sm text-muted-foreground\">\n                      {rollups.get(line.id)!.warning} warning ·{\" \"}\n                      {rollups.get(line.id)!.offline} offline ·{\" \"}\n                      {rollups.get(line.id)!.healthy} healthy\n                    </span>\n                  </dd>\n                </div>\n              </dl>\n            </Panel>\n\n            <div className=\"grid min-w-0 grid-cols-1 items-start gap-6 md:gap-8\">\n              <Panel aria-label={`Selected machine: ${device.name}`}>\n                <div className=\"flex min-w-0 flex-wrap items-start gap-4\">\n                  <DeviceIllustration\n                    category={category}\n                    on={isRunning(iot, deviceId)}\n                    size=\"md\"\n                    className=\"sm:size-28\"\n                  />\n                  <div className=\"flex min-w-0 flex-1 flex-col gap-1\">\n                    <h4 className=\"text-title-lg text-foreground\">\n                      {device.name}\n                    </h4>\n                    <p className=\"text-body-md text-muted-foreground\">\n                      {lineName}\n                    </p>\n                    <StateBadge state={inspectorState}>\n                      {down\n                        ? \"Offline. Showing the last known settings.\"\n                        : device.status === \"warning\"\n                          ? \"Needs attention\"\n                          : pending.length\n                            ? \"Requested, not yet confirmed\"\n                            : \"Confirmed\"}\n                    </StateBadge>\n                  </div>\n                  {power ? (\n                    <p\n                      className=\"flex w-full flex-col sm:w-auto sm:items-end sm:text-end\"\n                      aria-live=\"off\"\n                    >\n                      <span className=\"text-body-sm text-muted-foreground\">\n                        Reported\n                      </span>\n                      {/* The selected machine's CONFIRMED state: the largest thing in this region. */}\n                      <span className=\"text-headline-lg tabular-nums text-foreground\">\n                        {down\n                          ? \"Offline\"\n                          : isRunning(iot, deviceId)\n                            ? \"Running\"\n                            : \"Stopped\"}\n                      </span>\n                    </p>\n                  ) : null}\n                </div>\n\n                {power ? (\n                  <div\n                    role=\"group\"\n                    aria-label={`${device.name} controls`}\n                    className={`flex min-w-0 flex-col gap-4 rounded-xl bg-muted/60 p-4 ${pending.length ? \"border-2 border-dashed border-primary\" : \"\"}`}\n                  >\n                    <div className=\"flex min-w-0 items-center justify-between gap-4\">\n                      <div className=\"flex min-w-0 flex-col\">\n                        <span className=\"text-title-md text-foreground\">\n                          Run\n                        </span>\n                        <span className=\"text-body-md text-muted-foreground\">\n                          {power.format(power.confirmed)}\n                          {power.requested !== undefined\n                            ? `, requested ${power.format(power.requested)} — not yet confirmed`\n                            : \"\"}\n                        </span>\n                      </div>\n                      <DevicePowerControl\n                        state={power.confirmed as \"on\" | \"off\"}\n                        requested={power.requested as \"on\" | \"off\" | undefined}\n                        control={power.control}\n                        label={`${device.name} run`}\n                        size=\"lg\"\n                        showLabel={false}\n                        onToggle={power.send}\n                      />\n                    </div>\n                    <Lifecycle binding={power} />\n                    {level && levelCap ? (\n                      <>\n                        {/* The `track` variant, not `pill`: at 326px the pill's inline label and value had\n                            nowhere to go and clipped, and the track also words a pending request. */}\n                        <DeviceLevelControl\n                          value={level.confirmed as number}\n                          target={level.requested as number | undefined}\n                          unit=\"%\"\n                          step={5}\n                          control={level.control}\n                          label={levelCap.label ?? levelCap.id}\n                          onCommit={level.send}\n                        />\n                        <Lifecycle binding={level} />\n                      </>\n                    ) : null}\n                  </div>\n                ) : (\n                  <p className=\"rounded-xl bg-muted/60 p-4 text-body-md text-muted-foreground\">\n                    {down\n                      ? \"This device is offline. It reports nothing and accepts no commands until it reconnects.\"\n                      : \"Read-only device: it reports, and has nothing to command.\"}\n                  </p>\n                )}\n              </Panel>\n\n              {/* Tertiary: how the device is connected and what firmware it runs. Present and complete,\n                  but behind a disclosure on a phone so it does not sit beside the run control. */}\n              <Disclosure title=\"Connection and firmware\">\n                <div className=\"grid min-w-0 grid-cols-1 gap-4 sm:grid-cols-2\">\n                  <div className=\"min-w-0\">\n                    <ConnectionHealth\n                      device={device}\n                      freshnessMs={STALE_AFTER_MS}\n                      now={sim.now}\n                      aria-label={`${device.name} connection`}\n                    />\n                  </div>\n                  <div className=\"flex min-w-0 flex-col gap-3\">\n                    <div className=\"flex flex-wrap items-center justify-between gap-2\">\n                      <span className=\"text-body-md text-muted-foreground\">\n                        Signal\n                      </span>\n                      <SignalStrength value={down ? null : device.signal} />\n                    </div>\n                    {device.battery !== undefined ? (\n                      <div className=\"flex flex-wrap items-center justify-between gap-2\">\n                        <span className=\"text-body-md text-muted-foreground\">\n                          Battery\n                        </span>\n                        <BatteryIndicator value={device.battery} />\n                      </div>\n                    ) : null}\n                    <FirmwareStatus\n                      showVersions\n                      firmware={{\n                        currentVersion: device.firmwareVersion,\n                        availableVersion:\n                          availableFirmware ?? device.firmwareVersion,\n                        status: availableFirmware\n                          ? \"update-available\"\n                          : \"up-to-date\",\n                      }}\n                    />\n                    {availableFirmware ? (\n                      <p className=\"text-body-sm text-muted-foreground\">\n                        Availability is application-provided demo data. No\n                        update is sent.\n                      </p>\n                    ) : null}\n                  </div>\n                </div>\n              </Disclosure>\n\n              <Disclosure\n                title=\"Telemetry\"\n                count={metrics.length}\n                countNoun=\"metrics\"\n              >\n                {metrics.length === 0 ? (\n                  <p className=\"text-body-md text-muted-foreground\">\n                    This device reports no measurements.\n                  </p>\n                ) : (\n                  <>\n                    {down ? (\n                      <p className=\"rounded-xl bg-muted/60 p-3 text-body-md text-foreground\">\n                        Offline since{\" \"}\n                        {formatRelativeTime(device.lastSeenAt ?? \"\", {\n                          now: sim.now,\n                        })}\n                        . The figures below are the last history, marked stale,\n                        not current readings.\n                      </p>\n                    ) : null}\n                    <TelemetryGrid label={`${device.name} readings`}>\n                      {metrics.map((metric) => (\n                        <TelemetryMetric\n                          key={metric}\n                          {...metricProps(metric)}\n                          size=\"lg\"\n                        />\n                      ))}\n                    </TelemetryGrid>\n                    <div className=\"grid min-w-0 grid-cols-1 gap-6 md:grid-cols-2 xl:grid-cols-3\">\n                      {metrics\n                        .filter(\n                          (metric) =>\n                            trendOf(iot, deviceId, metric).series.points\n                              .length > 1,\n                        )\n                        .map((metric) => (\n                          <div\n                            key={metric}\n                            className=\"flex min-w-0 flex-col gap-2\"\n                          >\n                            <h5 className=\"text-title-sm text-foreground\">\n                              {METRIC_LABEL[metric] ?? metric} trend\n                            </h5>\n                            <TelemetryTrend\n                              {...trendOf(iot, deviceId, metric)}\n                              staleAfterMs={STALE_AFTER_MS}\n                              label={`${device.name} ${METRIC_LABEL[metric] ?? metric}`}\n                              height={120}\n                              precision={1}\n                              showSummary\n                              dataTable\n                            />\n                          </div>\n                        ))}\n                    </div>\n                  </>\n                )}\n              </Disclosure>\n            </div>\n          </div>\n        </div>\n\n        <div className=\"grid min-w-0 grid-cols-1 content-start items-start gap-4 md:grid-cols-2 xl:grid-cols-3\">\n          <Disclosure\n            title=\"Shift log\"\n            count={selectActivity(sim).length}\n            countNoun=\"events\"\n          >\n            <ActivityTimeline\n              variant=\"blocks\"\n              events={selectActivity(sim, { limit: 6 })}\n              deviceName={(id) => deviceOf(sim, id).name}\n              now={sim.now}\n              label=\"Shift log\"\n            />\n          </Disclosure>\n\n          <Disclosure\n            title=\"Routines\"\n            count={sim.automations.length}\n            countNoun=\"routines\"\n          >\n            <p className=\"text-body-sm text-muted-foreground\">\n              Shown, not executed: KinetixUI has no automation engine.\n            </p>\n            <div className=\"flex flex-col gap-3\">\n              {sim.automations.map((automation) => {\n                const on = enabled[automation.id] ?? automation.enabled;\n                return (\n                  <RoutineCard\n                    key={automation.id}\n                    automation={{\n                      ...automation,\n                      enabled: on,\n                      status: on\n                        ? automation.status === \"disabled\"\n                          ? \"idle\"\n                          : automation.status\n                        : \"disabled\",\n                    }}\n                    now={sim.now}\n                    onToggleEnabled={(next) =>\n                      setEnabled((prev) => ({ ...prev, [automation.id]: next }))\n                    }\n                  />\n                );\n              })}\n            </div>\n          </Disclosure>\n\n          {energy ? (\n            <Disclosure title=\"Energy today\" defaultOpen={false}>\n              <EnergySummary\n                presentation=\"sparkline\"\n                summary={energy.summary}\n                today={energy.summary.total}\n                days={energy.week}\n                dayLabels={dayLabels}\n                updatedLabel=\"Simulated, updates with the clock\"\n              />\n            </Disclosure>\n          ) : null}\n        </div>\n      </div>\n    </section>\n  );\n}",
  "device-detail": "/**\n * One device as a product view rather than a settings page. The device is the pump station of the farm\n * scenario, and the page is composed in two zones:\n *\n *   - the ZONE OF ACTION: who the device is, the one control that matters, and what it is measuring;\n *   - the ZONE OF CONTEXT: what needs attention, what happened, what is scheduled, how healthy it is.\n *\n * Below `lg` the two zones become one designed column: the control first, the readings second, and the\n * rest behind disclosures that say how much is inside. The large \"Running / Stopped\" word is the\n * CONFIRMED state. A request that has not landed appears beneath it as its own dashed, worded\n * treatment, and never replaces it.\n *\n * SIMULATED. Nothing configures hardware and nothing is sent; the routines are SHOWN, never executed.\n */\nconst DEVICE_ID = \"pump-01\";\nconst METRICS = [\n  { id: \"flow\", label: \"Flow\" },\n  { id: \"pressure\", label: \"Pressure\" },\n] as const;\n\nexport function DeviceDetailExample() {\n  const iot = useIotSimulation(agritech, { intervalMs: 1000 });\n  const { sim } = iot;\n  const [metric, setMetric] = React.useState<(typeof METRICS)[number][\"id\"]>(\"flow\");\n\n  const device = deviceOf(sim, DEVICE_ID);\n  const state = selectDeviceState(sim, DEVICE_ID)!;\n  const power = controlOf(iot, DEVICE_ID, \"power\");\n  const tree = React.useMemo(() => buildSpaceTree(sim.scenario.spaces), [sim.scenario.spaces]);\n  const home = sim.scenario.spaces.find((space) => space.deviceIds?.includes(DEVICE_ID));\n\n  // CONFIRMED: what the pump last reported. `requested` is separate and only ever shown as a request.\n  const running = state.confirmedValues.power === \"on\";\n  const online = device.status === \"online\";\n  const requestedPower = power.requested as \"on\" | \"off\" | undefined;\n  const alerts = state.alerts.filter((alert) => !alert.resolvedAt);\n  const routines = sim.automations.filter((automation) => automation.actions?.toLowerCase().includes(\"pump\"));\n  const rules = sim.scenario.rules.filter((rule) => rule.actions.some((action) => action.target === DEVICE_ID));\n  const activity = selectActivity(sim, { deviceId: DEVICE_ID });\n  const health: ShowcaseState = !online ? \"offline\" : state.health.level === \"critical\" ? \"critical\" : state.health.level === \"warning\" ? \"warning\" : \"confirmed\";\n  const flow = readingOf(iot, DEVICE_ID, \"flow\");\n  const pressure = readingOf(iot, DEVICE_ID, \"pressure\");\n\n  return (\n    <article aria-label={`${device.name} detail`} className=\"flex flex-col gap-4 sm:gap-6\">\n      <SimNotice scenario={agritech}>\n        <SimTransport iot={iot} />\n      </SimNotice>\n\n      {/* ------------------------------------------------------------------ identity */}\n      <header className=\"flex min-w-0 flex-col gap-3\">\n        <div className=\"flex min-w-0 items-center gap-4\">\n          <span\n            aria-hidden=\"true\"\n            className={cn(\n              \"flex size-16 shrink-0 items-center justify-center rounded-2xl p-2 transition-colors duration-fast motion-reduce:transition-none sm:size-28\",\n              running && online ? \"bg-primary/10\" : \"bg-card shadow-sm\",\n            )}\n          >\n            <DeviceIllustration category={resolveDeviceCategory(device)} on={running && online} size=\"lg\" className=\"size-full\" />\n          </span>\n          <div className=\"flex min-w-0 flex-col gap-1\">\n            {/* Wraps rather than truncates: at 320 the illustration left too little room and the name was cut. */}\n            <h4 className=\"break-words text-headline-md text-foreground\">{device.name}</h4>\n            {home ? <SpaceBreadcrumb path={spacePath(tree, home.id)} label={`Location of ${device.name}`} /> : null}\n            <p className=\"flex flex-wrap items-center gap-x-4 gap-y-2 text-body-md\">\n              <DeviceStatusBadge status={device.status} />\n              <span className=\"text-muted-foreground\">\n                {/* LastSync's own accessible label is the whole sentence (\"Last seen 4 seconds ago\"); the\n                    visible prefix is hidden from assistive technology so it is not read twice. */}\n                <span aria-hidden=\"true\">Last seen </span>\n                <LastSync value={device.lastSeenAt} now={sim.now} />\n              </span>\n              {alerts.length > 0 ? (\n                <StateBadge state=\"warning\">\n                  {alerts.length} open {alerts.length === 1 ? \"alert\" : \"alerts\"}\n                </StateBadge>\n              ) : null}\n            </p>\n          </div>\n        </div>\n      </header>\n\n      <div className=\"grid min-w-0 gap-4 sm:gap-6 lg:grid-cols-[minmax(0,3fr)_minmax(0,2fr)] lg:items-start\">\n        {/* ============================================================ zone of action */}\n        <div className=\"flex min-w-0 flex-col gap-4 sm:gap-6\">\n          <section aria-label=\"Pump control\" className=\"flex min-w-0 flex-col gap-5 rounded-2xl bg-card p-4 shadow-sm sm:p-6\">\n            <div className=\"flex min-w-0 flex-col gap-1\">\n              <div className=\"flex flex-wrap items-center justify-between gap-2\">\n                <p className=\"text-body-md text-muted-foreground\">Pump status</p>\n                <StateBadge state={online ? \"confirmed\" : \"offline\"}>{online ? \"Confirmed by the pump\" : \"Last known, pump offline\"}</StateBadge>\n              </div>\n              {/* The word \"Running\" is the CONFIRMED state. A request in flight is never shown here. */}\n              {/* The request sits under the confirmed word as a full-width block, not beside it as a pill:\n                  at phone width a rounded pill wrapped its sentence into a lozenge, and this has to stay\n                  readable to stay honest. */}\n              <p className=\"flex min-w-0 flex-col items-start gap-2 text-display-sm text-foreground\">\n                <span>{running ? \"Running\" : \"Stopped\"}</span>\n                {requestedPower !== undefined ? (\n                  <span className=\"flex min-w-0 items-start gap-2 self-stretch rounded-xl border-2 border-dashed border-primary bg-primary/10 p-3 text-body-md font-medium text-foreground\">\n                    <StateGlyph state=\"pending\" className=\"mt-0.5 text-primary\" />\n                    {power.format(requestedPower)} requested, not yet confirmed. The pump still reports {running ? \"running\" : \"stopped\"}.\n                  </span>\n                ) : null}\n              </p>\n              <p className=\"text-body-md text-muted-foreground\">{online ? `As last reported by the pump. ${describeConnectivity(state.connectivity.state)}.` : \"Offline. Showing the last known state.\"}</p>\n            </div>\n\n            <div className=\"flex min-w-0 flex-col gap-4 rounded-xl bg-muted/60 p-4\">\n              <div className=\"flex min-h-11 min-w-0 flex-col items-stretch gap-2 sm:flex-row sm:flex-wrap sm:items-center sm:justify-between sm:gap-x-4\">\n                <span className=\"text-title-md text-foreground\">Pump power</span>\n                <DevicePowerControl\n                  state={power.confirmed as \"on\" | \"off\"}\n                  requested={requestedPower}\n                  control={power.control}\n                  label={`${device.name} power`}\n                  size=\"lg\"\n                  onToggle={power.send}\n                />\n              </div>\n              {power.command && power.unsettled ? (\n                <CommandLifecycle lifecycle={power.command.lifecycle} formatValue={power.format} onRetry={power.retry} onCancel={power.cancel} density=\"compact\" />\n              ) : null}\n            </div>\n          </section>\n\n          <section aria-label=\"Readings\" className=\"flex min-w-0 flex-col gap-4 rounded-2xl bg-card p-4 shadow-sm sm:p-6\">\n            <div className=\"grid gap-3 sm:grid-cols-2\">\n              {/* One step below the confirmed \"Running\": the readings are what the pump measures, not what it is. */}\n              <TelemetryMetric {...flow} label=\"Flow\" size=\"lg\" className=\"rounded-xl bg-muted/60 p-4\" />\n              <TelemetryMetric {...pressure} label=\"Pressure\" size=\"lg\" className=\"rounded-xl bg-muted/60 p-4\" />\n            </div>\n            <div className=\"flex min-w-0 flex-col gap-3\">\n              <div className=\"flex flex-wrap items-center justify-between gap-3\">\n                <h5 className=\"text-title-md text-foreground\">Last 24 hours</h5>\n                <PillSelector label=\"Chart metric\" options={METRICS} value={metric} onChange={(id) => setMetric(id as (typeof METRICS)[number][\"id\"])} className=\"rounded-full bg-muted/60 p-1\" />\n              </div>\n              <TelemetryTrend {...trendOf(iot, DEVICE_ID, metric)} label={metric === \"flow\" ? \"Pump flow, last 24 hours\" : \"Pump pressure, last 24 hours\"} height={160} dataTable />\n              {metric === \"flow\" ? <p className=\"text-body-sm text-muted-foreground\">The band below 20 L/min is the low-flow limit. Gaps are drawn as gaps.</p> : null}\n            </div>\n          </section>\n\n          <Disclosure title=\"About this device\" defaultOpen={false}>\n            <dl className=\"m-0 grid grid-cols-2 gap-x-6 gap-y-4 text-body-md\">\n              {(\n                [\n                  [\"Device id\", device.id],\n                  [\"Type\", device.type],\n                  [\"Firmware\", device.firmwareVersion ?? \"Not reported\"],\n                  [\"Site\", device.site ?? \"Not set\"],\n                  [\"Zone\", device.zone ?? \"Not set\"],\n                  [\"Battery\", device.battery === undefined ? \"Not reported\" : `${device.battery}%`],\n                ] as const\n              ).map(([term, value]) => (\n                <div key={term} className=\"min-w-0\">\n                  <dt className=\"text-body-sm text-muted-foreground\">{term}</dt>\n                  <dd className=\"m-0 break-words text-foreground\">{value}</dd>\n                </div>\n              ))}\n            </dl>\n            <p className=\"text-body-sm text-muted-foreground\">Read-only. Nothing here configures hardware; it presents what the product knows.</p>\n          </Disclosure>\n        </div>\n\n        {/* ============================================================ zone of context */}\n        <div className=\"flex min-w-0 flex-col gap-4 sm:gap-6\">\n          <Disclosure title=\"Alerts\" count={alerts.length} countNoun=\"open alerts\" defaultOpen={alerts.length > 0 ? true : undefined}>\n            <AlertList alerts={alerts} deviceName={() => undefined} onAcknowledge={(alert) => iot.acknowledgeAlert(alert.id)} now={sim.now} emptyLabel=\"No open alerts.\" hideSummary variant=\"list\" />\n          </Disclosure>\n\n          <Disclosure title=\"Health and connection\">\n            <div className=\"flex flex-col gap-1\">\n              <p className=\"text-title-md text-foreground\">\n                {describeDeviceHealth(state.health.level)} · {describeConnectivity(state.connectivity.state)}\n              </p>\n              <p className=\"flex items-center gap-2 text-body-md text-muted-foreground\">\n                <StateBadge state={health}>{state.health.reasons.length === 0 ? \"No issues reported.\" : state.health.reasons.map((reason) => reason.message).join(\", \")}</StateBadge>\n              </p>\n            </div>\n            <ConnectionHealth device={device} now={sim.now} />\n          </Disclosure>\n\n          <Disclosure title=\"Automation\" count={routines.length + rules.length} countNoun=\"routines and rules\">\n            <p className=\"text-body-sm text-muted-foreground\">Shown, not executed: KinetixUI has no automation engine.</p>\n            {routines.map((automation) => (\n              <RoutineCard key={automation.id} automation={automation} now={sim.now} />\n            ))}\n            {rules.map((rule) => (\n              <AutomationRuleView key={rule.id} rule={rule} />\n            ))}\n            {routines.length + rules.length === 0 ? <p className=\"text-body-md text-muted-foreground\">No routine or rule involves this pump.</p> : null}\n          </Disclosure>\n\n          <Disclosure title=\"Activity\" count={activity.length} countNoun=\"events\">\n            <ActivityTimeline events={activity} deviceName={() => undefined} now={sim.now} label={`${device.name} activity`} variant=\"blocks\" />\n          </Disclosure>\n        </div>\n      </div>\n    </article>\n  );\n}",
  "automation-builder": "/**\n * A rule editor wired to the farm's own vocabulary. It starts from the rule:\n *\n *   When soil moisture falls below 28% (and rain is not expected), open Zone 3 irrigation for 12 minutes.\n *\n * `AutomationBuilder` edits DATA. It validates with `validateAutomationRule`, shows problems inline,\n * and only calls `onSubmit` for a valid rule. Nothing evaluates the rule and nothing is sent: saving\n * here stores the rule in this component's state and says so.\n *\n * The rain forecast is application-provided demo data. KinetixUI fetches no forecast.\n */\nconst SUBJECTS: readonly KinetixBuilderSubject[] = [\n  { id: \"soil-moisture\", label: \"Soil moisture\", unit: \"%\" },\n  { id: \"rain-forecast\", label: \"Rain forecast\" },\n  { id: \"air-temperature\", label: \"Air temperature\", unit: \"°C\" },\n];\n\nconst TARGETS: readonly KinetixBuilderTarget[] = [\n  { id: \"zone-3\", label: \"Zone 3 irrigation\", commands: [{ id: \"open\", label: \"Open\" }, { id: \"close\", label: \"Close\" }] },\n  { id: \"zone-2\", label: \"Zone 2 irrigation\", commands: [{ id: \"open\", label: \"Open\" }, { id: \"close\", label: \"Close\" }] },\n  { id: \"pump-01\", label: \"Pump Station\", commands: [{ id: \"turn-on\", label: \"Turn on\" }, { id: \"turn-off\", label: \"Turn off\" }] },\n];\n\nconst BLANK: KinetixAutomationRule = { id: \"rule-new\", name: \"\", enabled: true, conditions: [], actions: [] };\nconst nameOf = (_kind: \"subject\" | \"scope\" | \"target\", id: string) =>\n  SUBJECTS.find((s) => s.id === id)?.label.toLowerCase() ?? TARGETS.find((t) => t.id === id)?.label;\n\nexport function AutomationBuilderExample() {\n  const [draft, setDraft] = React.useState<KinetixAutomationRule>(agritechRule);\n  const [saved, setSaved] = React.useState<KinetixAutomationRule | null>(null);\n\n  return (\n    <section aria-label=\"Automation builder\" className=\"flex flex-col gap-4 sm:gap-6\">\n      <SimNotice scenario={agritech} />\n\n      <div className=\"flex flex-col gap-4\">\n        <p className=\"text-body-md text-muted-foreground\">Edited as data. Nothing evaluates the rule and nothing is sent.</p>\n        <div className=\"flex flex-wrap gap-2\">\n          <button type=\"button\" className={cn(BUTTON, \"min-h-11 rounded-full px-4 text-body-md md:min-h-9\")} onClick={() => setDraft(BLANK)}>\n            Start from a blank rule\n          </button>\n          <button type=\"button\" className={cn(BUTTON, \"min-h-11 rounded-full px-4 text-body-md md:min-h-9\")} onClick={() => setDraft(agritechRule)}>\n            Reset to the Zone 3 rule\n          </button>\n        </div>\n\n        <AutomationBuilder\n          value={draft}\n          onChange={setDraft}\n          subjects={SUBJECTS}\n          targets={TARGETS}\n          labelFor={nameOf}\n          submitLabel=\"Save as demo state\"\n          onSubmit={(rule) => setSaved(rule)}\n        />\n      </div>\n\n      {saved ? (\n        <div role=\"status\" className=\"flex flex-col gap-3 rounded-2xl bg-card p-4 shadow-sm sm:p-6\">\n          <StateBadge state=\"confirmed\" className=\"text-title-md\">\n            Saved as demo state — nothing is executed.\n          </StateBadge>\n          <p className=\"text-body-md text-muted-foreground\">\n            The rule is {saved.enabled ? \"enabled\" : \"disabled\"}: {summarizeAutomationRule(saved, { label: nameOf })}\n          </p>\n          <AutomationRuleView rule={saved} labelFor={nameOf} hideSummary />\n        </div>\n      ) : null}\n    </section>\n  );\n}",
  "pairing-flow": "/**\n * A nine-step pairing reference. The steps a person sees:\n *\n *   1 choose a method   2 searching   3 device found   4 identify   5 verify it is yours\n *   6 configure         7 choose a place   8 check it works   9 done\n *\n * The state machine is the package's, not this file's: `advancePairing` / `transitionPairing` decide\n * what may follow what, and this component only reports intent to it. \"Searching\" and \"found\" are two\n * screens inside the machine's one `discover` stage.\n *\n * NO Bluetooth, Wi-Fi or network scanning happens. Durations come from a fixture and run on a small\n * timer here. Under `prefers-reduced-motion` there are no timers: each simulated wait is finished by a\n * button instead, so nothing advances on its own.\n */\nconst UI_STEPS = [\"Choose a method\", \"Searching\", \"Device found\", \"Identify\", \"Verify it is yours\", \"Configure\", \"Choose a place\", \"Check it works\", \"Done\"] as const;\nconst PLACES = [\"Living room\", \"Hallway\", \"Kitchen\", \"Office\", \"Bedroom\", \"Zone 2\", \"Zone 3\", \"Utility yard\"];\nconst DEMO_CODE = \"KX2468\";\n/** The step's one primary action, a filled pill; everything else is quiet. */\nconst ACTION =\n  \"inline-flex min-h-11 items-center justify-center self-start rounded-full bg-primary px-6 text-body-md font-medium text-primary-foreground shadow-sm hover:bg-primary/90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background disabled:cursor-not-allowed disabled:opacity-50 motion-reduce:transition-none\";\nconst QUIET = cn(BUTTON, \"min-h-11 rounded-full bg-card px-5 text-body-md shadow-sm\");\n/** Stages that begin with a simulated wait; the others begin by asking the person for something. */\nconst STARTS_WORKING: readonly KinetixPairingStage[] = [\"discover\", \"identify\", \"verify\"];\nconst durationOf = (stage: KinetixPairingStage) => pairingHappyPath.find((step) => step.stage === stage)?.durationMs ?? 1000;\n\nfunction uiStepOf(flow: KinetixPairingFlowState, working: boolean): number {\n  if (flow.status === \"idle\" || flow.status === \"cancelled\") return 0;\n  switch (flow.stage) {\n    case \"discover\":\n      return working || flow.status === \"failed\" ? 1 : 2;\n    case \"identify\":\n      return 3;\n    case \"authenticate\":\n      return 4;\n    case \"configure\":\n      return 5;\n    case \"assign\":\n      return 6;\n    case \"verify\":\n      return 7;\n    default:\n      return 8;\n  }\n}\n\nexport function PairingFlowExample() {\n  const reducedMotion = useReducedMotion();\n  const [flow, setFlow] = React.useState<KinetixPairingFlowState>(startPairingFlow);\n  // `visit` counts every flow change, so \"which wait am I in\" can never leak from an earlier visit to a stage.\n  const [visit, setVisit] = React.useState(0);\n  const [waiting, setWaiting] = React.useState<{ visit: number; working: boolean } | null>(null);\n  const [method, setMethod] = React.useState<KinetixPairingMethod>(\"bluetooth\");\n  const [scenarioId, setScenarioId] = React.useState(\"none\");\n  const [recovered, setRecovered] = React.useState(false);\n  const [foundId, setFoundId] = React.useState<string | null>(null);\n  const [code, setCode] = React.useState(\"\");\n  const [name, setName] = React.useState(\"\");\n  const [place, setPlace] = React.useState(PLACES[0]!);\n  const [note, setNote] = React.useState(\"\");\n  const headingRef = React.useRef<HTMLHeadingElement>(null);\n  const failureRef = React.useRef<HTMLDivElement>(null);\n  const mounted = React.useRef(false);\n\n  const scenario = pairingFailureScenarios.find((s) => s.id === scenarioId);\n  const found = pairingDevices[flow.method ?? method].find((d) => d.id === foundId) ?? pairingDevices[flow.method ?? method][0]!;\n  const acceptedCode = found.code ?? DEMO_CODE;\n  const codeLength = normalizePairingCode(acceptedCode).length;\n  const codeShapeOk = validatePairingCode(code, { length: codeLength });\n\n  const working = waiting?.visit === visit ? waiting.working : STARTS_WORKING.includes(flow.stage) && flow.status === \"active\";\n  const uiStep = uiStepOf(flow, working);\n  const started = flow.status !== \"idle\";\n\n  /** Every change to the flow goes through here, and always through the package's machine. */\n  const apply = (next: KinetixPairingFlowState) => {\n    setFlow(next);\n    setVisit((v) => v + 1);\n    setNote(\"\");\n  };\n  const send = (event: KinetixPairingEvent) => apply(advancePairing(flow, event));\n  const replayTo = (stage: KinetixPairingStage) => {\n    let state = advancePairing(startPairingFlow(), { type: \"start\", method: flow.method ?? method });\n    while (state.stage !== stage && state.status === \"active\") state = advancePairing(state, { type: \"next\" });\n    apply(state);\n  };\n  const setWorking = (value: boolean) => setWaiting({ visit, working: value });\n\n  /** A simulated wait has finished: the scripted failure strikes here, or the flow moves on. */\n  const workDone = () => {\n    if (flow.status !== \"active\") return;\n    const struck = scenario && !recovered && scenario.stage === flow.stage;\n    if (struck) return send({ type: \"fail\", code: scenario.code });\n    if (flow.stage === \"authenticate\" && normalizePairingCode(code) !== normalizePairingCode(acceptedCode)) {\n      return send({ type: \"fail\", code: \"authentication-failed\" });\n    }\n    if (flow.stage === \"discover\" || flow.stage === \"identify\") return setWorking(false);\n    send({ type: \"next\" });\n  };\n\n  React.useEffect(() => {\n    if (!working || flow.status !== \"active\" || reducedMotion) return;\n    const timer = setTimeout(workDone, durationOf(flow.stage));\n    return () => clearTimeout(timer);\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [working, visit, reducedMotion]);\n\n  React.useEffect(() => {\n    if (!mounted.current) {\n      mounted.current = true;\n      return;\n    }\n    (flow.status === \"failed\" ? failureRef.current : headingRef.current)?.focus();\n  }, [uiStep, flow.status, visit]);\n\n  const recover = (kind: KinetixPairingRecoveryKind) => {\n    const strikes = !!scenario && scenario.stage === flow.stage;\n    if (kind === \"retry\") {\n      if (strikes) setRecovered(true);\n      setCode(\"\");\n      return send({ type: \"retry\" });\n    }\n    if (kind === \"back\") return send({ type: \"back\" });\n    if (kind === \"cancel\") return send({ type: \"cancel\" });\n    if (kind === \"reset\") {\n      setRecovered(true);\n      return replayTo(\"discover\");\n    }\n    if (kind === \"update\") {\n      setRecovered(true);\n      return replayTo(flow.stage);\n    }\n    setNote(kind === \"contact\" ? \"In a product this would open help. Nothing happens in this demo.\" : \"In a product this would open settings. Nothing happens in this demo.\");\n  };\n\n  const startOver = () => {\n    setFlow(startPairingFlow());\n    setVisit((v) => v + 1);\n    setRecovered(false);\n    setCode(\"\");\n    setNote(\"\");\n    setFoundId(null);\n  };\n\n  const pickScenario = (id: string) => {\n    setScenarioId(id);\n    setRecovered(false);\n    const next = pairingFailureScenarios.find((s) => s.id === id);\n    if (next) setMethod(next.method);\n  };\n  const backAllowed = transitionPairing(flow, { type: \"back\" }).ok;\n  const cancelAllowed = transitionPairing(flow, { type: \"cancel\" }).ok;\n\n  const heading = flow.status === \"cancelled\" ? \"Setup cancelled\" : `Step ${uiStep + 1} of ${UI_STEPS.length}: ${UI_STEPS[uiStep]}`;\n\n  return (\n    <section aria-label=\"Pairing flow\" className=\"flex max-w-3xl flex-col gap-4 sm:gap-6\">\n      <SimNotice text=\"Simulated — no Bluetooth, Wi-Fi or network scanning happens. Devices, codes and delays are scripted fixtures in your browser.\" />\n\n      <label className=\"flex flex-col gap-1 text-body-md text-foreground\">\n        Simulate a failure\n        <select\n          value={scenarioId}\n          disabled={started && flow.status !== \"cancelled\"}\n          onChange={(event) => pickScenario(event.target.value)}\n          className=\"min-h-11 rounded-md border border-input bg-background px-2 text-label-md text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:opacity-60\"\n        >\n          <option value=\"none\">None: pair successfully</option>\n          {pairingFailureScenarios.map((s) => (\n            <option key={s.id} value={s.id}>\n              {s.title} ({describePairingMethod(s.method)}, {s.code})\n            </option>\n          ))}\n        </select>\n        {scenario ? <span className=\"text-body-sm text-muted-foreground\">{scenario.recoveryOutcome}</span> : null}\n      </label>\n\n      <PairingStepper flow={flow} horizontal />\n\n      <div className=\"flex min-w-0 flex-col gap-4 rounded-2xl bg-card p-4 shadow-sm sm:p-6\">\n        <h4 ref={headingRef} tabIndex={-1} className=\"text-title-lg text-foreground focus-visible:outline-none\">\n          {heading}\n        </h4>\n\n        {flow.status === \"failed\" ? (\n          <PairingFailure ref={failureRef} tabIndex={-1} code={flow.failure} onAction={(_id, action) => recover(action.kind)} className=\"focus-visible:outline-none\" />\n        ) : null}\n\n        {flow.status === \"cancelled\" ? (\n          <>\n            <p className=\"text-body-md text-muted-foreground\">Nothing was set up, and nothing was stored.</p>\n            <button type=\"button\" className={ACTION} onClick={startOver}>\n              Start again\n            </button>\n          </>\n        ) : null}\n\n        {flow.status === \"idle\" ? (\n          <>\n            <PairingMethodPicker\n              value={method}\n              methods={KINETIX_PAIRING_METHODS}\n              onChange={(next) => {\n                setMethod(next);\n                if (scenario && scenario.method !== next) setScenarioId(\"none\");\n              }}\n            />\n            <button type=\"button\" className={ACTION} onClick={() => send({ type: \"start\", method })}>\n              Start setup\n            </button>\n          </>\n        ) : null}\n\n        {flow.status === \"active\" && working ? (\n          <>\n            <p className=\"text-body-md text-muted-foreground\">\n              {pairingHappyPath.find((s) => s.stage === flow.stage)?.label}… (simulated, about {(durationOf(flow.stage) / 1000).toFixed(1)} s)\n            </p>\n            {reducedMotion ? (\n              <button type=\"button\" className={ACTION} onClick={workDone}>\n                Finish this step\n              </button>\n            ) : null}\n          </>\n        ) : null}\n\n        {flow.status === \"active\" && !working && flow.stage === \"discover\" ? (\n          <fieldset className=\"m-0 flex min-w-0 flex-col gap-2 border-0 p-0\">\n            <legend className=\"mb-1 text-title-md text-foreground\">\n              {pairingDevices[flow.method!].length} sample {pairingDevices[flow.method!].length === 1 ? \"device\" : \"devices\"} found (fixture data)\n            </legend>\n            {pairingDevices[flow.method!].map((device) => (\n              <label key={device.id} className=\"flex min-h-11 items-center gap-2 rounded-xl bg-muted/60 px-4 text-body-md text-foreground has-[:checked]:bg-primary/10 has-[:checked]:ring-2 has-[:checked]:ring-primary\">\n                <input type=\"radio\" name=\"found-device\" className=\"size-5\" checked={found.id === device.id} onChange={() => setFoundId(device.id)} />\n                <span className=\"min-w-0 break-words\">\n                  {device.name} <span className=\"text-muted-foreground\">· {device.hint}</span>\n                </span>\n              </label>\n            ))}\n            <button type=\"button\" className={ACTION} onClick={() => send({ type: \"next\" })}>\n              Continue with {found.name}\n            </button>\n          </fieldset>\n        ) : null}\n\n        {flow.status === \"active\" && !working && flow.stage === \"identify\" ? (\n          <>\n            <p className=\"text-body-md text-foreground\">\n              Does <strong className=\"font-medium\">{found.hint}</strong> match the label on your {found.name}?\n            </p>\n            <button type=\"button\" className={ACTION} onClick={() => send({ type: \"next\" })}>\n              Yes, that is my device\n            </button>\n          </>\n        ) : null}\n\n        {flow.status === \"active\" && !working && flow.stage === \"authenticate\" ? (\n          <form\n            className=\"flex min-w-0 flex-col gap-2\"\n            onSubmit={(event) => {\n              event.preventDefault();\n              if (codeShapeOk) setWorking(true);\n            }}\n          >\n            <label htmlFor=\"pairing-code\" className=\"text-body-md text-foreground\">\n              Setup code\n            </label>\n            <input\n              id=\"pairing-code\"\n              value={code}\n              onChange={(event) => setCode(event.target.value)}\n              autoComplete=\"off\"\n              spellCheck={false}\n              aria-describedby=\"pairing-code-hint\"\n              className=\"min-h-11 max-w-xs rounded-md border border-input bg-background px-3 font-mono text-label-md text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring\"\n            />\n            <p id=\"pairing-code-hint\" className=\"text-body-sm text-muted-foreground\">\n              {codeLength} characters. Demo code: <span className=\"font-mono text-foreground\">{acceptedCode}</span>. The shape is checked here; only the device can say whether it is the right code.\n            </p>\n            <button type=\"submit\" disabled={!codeShapeOk} className={ACTION}>\n              Verify code\n            </button>\n          </form>\n        ) : null}\n\n        {flow.status === \"active\" && !working && flow.stage === \"configure\" ? (\n          <form\n            className=\"flex min-w-0 flex-col gap-2\"\n            onSubmit={(event) => {\n              event.preventDefault();\n              setWorking(true);\n            }}\n          >\n            <label htmlFor=\"pairing-name\" className=\"text-body-md text-foreground\">\n              Device name\n            </label>\n            <input\n              id=\"pairing-name\"\n              value={name || found.name}\n              onChange={(event) => setName(event.target.value)}\n              className=\"min-h-11 max-w-xs rounded-md border border-input bg-background px-3 text-label-md text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring\"\n            />\n            <button type=\"submit\" className={ACTION}>\n              Apply settings\n            </button>\n          </form>\n        ) : null}\n\n        {flow.status === \"active\" && !working && flow.stage === \"assign\" ? (\n          <form\n            className=\"flex min-w-0 flex-col gap-2\"\n            onSubmit={(event) => {\n              event.preventDefault();\n              setWorking(true);\n            }}\n          >\n            <label htmlFor=\"pairing-place\" className=\"text-body-md text-foreground\">\n              Room or zone\n            </label>\n            <select\n              id=\"pairing-place\"\n              value={place}\n              onChange={(event) => setPlace(event.target.value)}\n              className=\"min-h-11 max-w-xs rounded-md border border-input bg-background px-2 text-label-md text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring\"\n            >\n              {PLACES.map((p) => (\n                <option key={p}>{p}</option>\n              ))}\n            </select>\n            <button type=\"submit\" className={ACTION}>\n              Place it here\n            </button>\n          </form>\n        ) : null}\n\n        {flow.status === \"complete\" ? (\n          <>\n            <p className=\"text-body-md text-foreground\">\n              {name || found.name} is set up in {place}. It responded when checked.\n            </p>\n            <p className=\"text-body-sm text-muted-foreground\">Simulated: no device was paired, connected to or stored.</p>\n            <button type=\"button\" className={ACTION} onClick={startOver}>\n              Pair another device\n            </button>\n          </>\n        ) : null}\n\n        {note ? <p className=\"text-body-sm text-muted-foreground\">{note}</p> : null}\n      </div>\n\n      {started && flow.status !== \"complete\" && flow.status !== \"cancelled\" ? (\n        <div className=\"flex flex-wrap gap-2\">\n          <button type=\"button\" className={QUIET} disabled={!backAllowed} onClick={() => send({ type: \"back\" })}>\n            Back\n          </button>\n          <button type=\"button\" className={QUIET} disabled={!cancelAllowed} onClick={() => send({ type: \"cancel\" })}>\n            Cancel setup\n          </button>\n        </div>\n      ) : null}\n    </section>\n  );\n}",
  "telemetry-history": "/**\n * Telemetry over time: twelve kinds of reading in the states a real fleet is actually in, then two\n * trends with a threshold band, a gap where the sensor did not answer, and the data table that backs\n * the chart for anyone who cannot read a line.\n *\n * SIMULATED, fabricated data measured from one fixed instant. Nothing is sampled from a device.\n */\nconst NOW = AGRITECH_START;\nconst ago = (ms: number) => new Date(Date.parse(NOW) - ms).toISOString();\nconst MINUTE = 60_000;\nconst HOUR = 60 * MINUTE;\n\nconst RANGES = [\n  { id: \"6h\", label: \"6 hours\", ms: 6 * HOUR },\n  { id: \"24h\", label: \"24 hours\", ms: 24 * HOUR },\n  { id: \"7d\", label: \"7 days\", ms: 7 * 24 * HOUR },\n] as const;\n\n/** Keep the points inside the window. A gap (`quality: \"missing\"`) survives the cut, so it still draws. */\nfunction within(series: KinetixTelemetrySeries | undefined, windowMs: number): KinetixTelemetrySeries {\n  const from = Date.parse(NOW) - windowMs;\n  return { deviceId: series?.deviceId ?? \"\", metric: series?.metric ?? \"\", points: (series?.points ?? []).filter((p) => Date.parse(String(p.timestamp)) >= from) };\n}\n\n/** One series: its newest value as a large numeral, then the chart and the table that backs it. */\nfunction ChartTile({ title, unit, note, series, thresholds, height }: { title: string; unit: string; note?: string; series: KinetixTelemetrySeries; thresholds?: { warningLow: number }; height: number }) {\n  const latest = [...series.points].reverse().find((point) => point.quality !== \"missing\" && typeof point.value === \"number\");\n  return (\n    <div className=\"flex min-w-0 flex-col gap-3 rounded-2xl bg-muted/40 p-4\">\n      <div className=\"flex min-w-0 flex-col gap-1\">\n        <h5 className=\"text-title-md text-foreground\">{title}</h5>\n        <p className=\"tabular-nums text-headline-lg text-foreground\">\n          {latest ? String(Math.round((latest.value as number) * 10) / 10) : \"No reading\"}\n          {latest ? <bdi className=\"ms-1 text-title-md text-muted-foreground\">{unit}</bdi> : null}\n        </p>\n        <p className=\"text-body-sm text-muted-foreground\">{note ?? \"Latest reading in this range.\"}</p>\n      </div>\n      <TelemetryTrend series={series} label={title} thresholds={thresholds} height={height} now={NOW} dataTable />\n    </div>\n  );\n}\n\nexport function TelemetryHistoryExample() {\n  const [range, setRange] = React.useState<(typeof RANGES)[number][\"id\"]>(\"7d\");\n  const windowMs = RANGES.find((r) => r.id === range)!.ms;\n  const find = (deviceId: string, metric: string) => agritech.series.find((s) => s.deviceId === deviceId && s.metric === metric);\n\n  return (\n    <section aria-label=\"Telemetry history\" className=\"flex flex-col gap-4 sm:gap-6\">\n      <SimNotice text=\"Simulated — fabricated readings measured from a fixed instant. Nothing is sampled from a device.\" />\n\n      <Panel title=\"Readings now\" description=\"Normal, warning, critical, stale and unavailable are different states, never one confident number.\">\n        <TelemetryGrid label=\"Readings by kind\" className=\"grid grid-cols-2 gap-2 sm:flex sm:gap-4\">\n          <TelemetryMetric size=\"lg\" metric=\"temperature\" value={24.6} timestamp={ago(20_000)} now={NOW} />\n          <TelemetryMetric size=\"lg\" metric=\"humidity\" value={88} thresholds={{ warningHigh: 80, criticalHigh: 95 }} timestamp={ago(20_000)} now={NOW} />\n          <TelemetryMetric size=\"lg\" metric=\"soil-moisture\" value={34} thresholds={{ warningLow: 28 }} timestamp={ago(40_000)} now={NOW} />\n          <TelemetryMetric size=\"lg\" metric=\"pressure\" value={null} quality=\"missing\" timestamp={ago(20_000)} now={NOW} />\n          <TelemetryMetric size=\"lg\" metric=\"air-quality\" value={212} timestamp={ago(10_000)} now={NOW} />\n          <TelemetryMetric size=\"lg\" metric=\"motion\" value={2} unit=\"events\" timestamp={ago(15_000)} now={NOW} />\n          <TelemetryMetric size=\"lg\" metric=\"light-level\" value={420} timestamp={ago(30_000)} now={NOW} />\n          <TelemetryMetric size=\"lg\" metric=\"flow\" value={18} thresholds={{ warningLow: 20 }} timestamp={ago(10_000)} now={NOW} />\n          <TelemetryMetric size=\"lg\" metric=\"water-level\" value={6} thresholds={{ warningLow: 20, criticalLow: 10 }} timestamp={ago(45_000)} now={NOW} />\n          <TelemetryMetric size=\"lg\" metric=\"power\" value={1820} timestamp={ago(5_000)} now={NOW} />\n          <TelemetryMetric size=\"lg\" metric=\"battery\" value={18} timestamp={ago(60_000)} now={NOW} />\n          <TelemetryMetric size=\"lg\" metric=\"signal-strength\" value={61} timestamp={ago(2 * HOUR)} staleAfterMs={15 * MINUTE} now={NOW} />\n        </TelemetryGrid>\n      </Panel>\n\n      <Panel title=\"History\" description=\"The band is the product-set threshold. A break in the line is a reading that was due and did not arrive.\">\n        <PillSelector label=\"Time range\" options={RANGES} value={range} onChange={(id) => setRange(id as (typeof RANGES)[number][\"id\"])} className=\"self-start rounded-full bg-muted/60 p-1\" />\n        <div className=\"grid gap-4 lg:grid-cols-2\">\n          <ChartTile title=\"Soil moisture, Zone 3\" unit=\"%\" series={within(find(\"soil-04\", \"soil-moisture\"), windowMs)} thresholds={{ warningLow: 28 }} height={160} />\n          <ChartTile title=\"Weather station temperature\" unit=\"°C\" note=\"With a gap where the sensor did not answer.\" series={within(find(\"weather-01\", \"temperature\"), Math.min(windowMs, 24 * HOUR))} height={160} />\n        </div>\n      </Panel>\n    </section>\n  );\n}",
  "alert-center": "/**\n * An alert centre over Site 04: fleet health above, the alert list below, and an acknowledge flow.\n *\n * Acknowledged is not resolved. Acknowledging says \"I have seen this\"; the alert stays in the list and\n * the device keeps counting against health until the condition itself clears. Use the button to make\n * another sensor stop answering and watch the counts and the list change together.\n *\n * SIMULATED: nothing is sent to a device, and acknowledging changes only this component's state.\n */\n/** One-line rows need room for the message; below 768px the fuller list rows read better. */\nfunction useWide(): boolean {\n  const [wide, setWide] = React.useState(false);\n  React.useEffect(() => {\n    if (typeof window.matchMedia !== \"function\") return;\n    const media = window.matchMedia(\"(min-width: 768px)\");\n    const read = () => setWide(media.matches);\n    read();\n    media.addEventListener?.(\"change\", read);\n    return () => media.removeEventListener?.(\"change\", read);\n  }, []);\n  return wide;\n}\n\nexport function AlertCenterExample() {\n  const wide = useWide();\n  const iot = useIotSimulation(operations, { intervalMs: 1000 });\n  const { sim } = iot;\n  const [showAcknowledged, setShowAcknowledged] = React.useState(true);\n  const silent = !sim.devices[\"s-101\"]!.reachable;\n  const alerts = selectAlerts(sim, { includeAcknowledged: showAcknowledged });\n\n  return (\n    <section aria-label=\"Alert centre\" className=\"flex flex-col gap-4 sm:gap-6\">\n      <SimNotice scenario={operations}>\n        <SimTransport iot={iot} />\n      </SimNotice>\n\n      <Panel title=\"Site 04 health\" description=\"Rolled up from every device on the site.\">\n        <DeviceHealthSummary summary={selectFleetHealth(sim)} noun={{ one: \"device\", other: \"devices\" }} size=\"lg\" />\n      </Panel>\n\n      <Panel title=\"Alerts\" description=\"Acknowledging says “I have seen this”. It does not resolve the alert.\">\n        <div className=\"flex flex-wrap items-center gap-3 rounded-xl bg-muted/60 p-3\">\n          <label className=\"flex min-h-11 cursor-pointer items-center gap-3 text-body-md text-foreground md:min-h-9\">\n            <input type=\"checkbox\" className=\"size-5\" checked={showAcknowledged} onChange={(event) => setShowAcknowledged(event.target.checked)} />\n            Show acknowledged\n          </label>\n          <button type=\"button\" className={cn(BUTTON, \"min-h-11 md:min-h-9\")} onClick={() => iot.setReachable(\"s-101\", silent)}>\n            {silent ? \"Vessel sensor S-101 answers again\" : \"Make Vessel sensor S-101 stop answering\"}\n          </button>\n        </div>\n        <AlertList\n          alerts={alerts}\n          deviceName={(id) => deviceOf(sim, id).name}\n          onAcknowledge={(alert) => iot.acknowledgeAlert(alert.id)}\n          now={sim.now}\n          emptyLabel=\"Nothing to show.\"\n          variant={wide ? \"compact\" : \"list\"}\n        />\n      </Panel>\n    </section>\n  );\n}",
  "device-fleet": "export function DeviceFleetExample() {\n  // Worst first. The ordering comes from KINETIX_DEVICE_STATUSES via compareDeviceAttention, so the\n  // list and the badges agree about which state is worse instead of holding two opinions.\n  const devices = [...DEMO_DEVICES].sort(compareDeviceAttention);\n\n  return (\n    <section aria-label=\"Device fleet\" className=\"flex flex-col gap-4 sm:gap-6\">\n      <header className=\"flex flex-wrap items-baseline justify-between gap-3\">\n        <h3 className=\"text-headline-sm text-foreground\">Cold chain · Site 4</h3>\n        <DeviceStateSummary devices={devices} />\n      </header>\n\n      <div className=\"grid grid-cols-[repeat(auto-fill,minmax(min(100%,17rem),1fr))] gap-3\">\n        {devices.map((device) => (\n          <DeviceCard\n            key={device.id}\n            device={device}\n            reading={DEMO_READINGS[device.id]}\n            now={DEMO_NOW}\n          />\n        ))}\n      </div>\n    </section>\n  );\n}",
  "telemetry-board": "export function TelemetryBoardExample() {\n  return (\n    <div className=\"flex flex-col gap-4\">\n      <div className=\"grid grid-cols-[repeat(auto-fit,minmax(min(100%,15rem),1fr))] gap-3\">\n        <TelemetryCard series={DEMO_SERIES.temperature} metric=\"Temperature\" precision={1} now={DEMO_NOW} />\n        <TelemetryCard series={DEMO_SERIES.humidity} metric=\"Humidity\" now={DEMO_NOW} />\n        <TelemetryCard series={DEMO_SERIES.load} metric=\"Load\" precision={1} now={DEMO_NOW} />\n        {/* This sensor stopped answering four hours ago. The card shows that rather than a last-known\n            value dressed up as current, and its plot stops where the readings stopped. */}\n        <TelemetryCard series={DEMO_SERIES.airQuality} metric=\"PM2.5\" now={DEMO_NOW} />\n      </div>\n\n      {/* The trend on its own, at the size a detail view would give it. The two dropouts in the load\n          series are breaks in the line and a count in the footer — never interpolated across. */}\n      <figure className=\"m-0 flex flex-col gap-3 rounded-2xl bg-card p-4 shadow-sm sm:p-6\">\n        <figcaption className=\"text-title-md text-foreground\">\n          Load · last 3 hours\n        </figcaption>\n        <TelemetryTrend series={DEMO_SERIES.load} precision={1} height={160} />\n      </figure>\n    </div>\n  );\n}",
  "connection-troubleshooting": "/**\n * Six devices that a single \"offline\" dot would describe identically, and the facts that tell them\n * apart. The library does not diagnose the cause — it has no transport and cannot know whether a\n * gateway died or a firewall changed — it separates the signals so a person can.\n */\nconst CASES: { device: KinetixDevice; what: string }[] = [\n  { device: deviceById(\"probe-a\"), what: \"Reporting on schedule. Nothing to do.\" },\n  { device: deviceById(\"probe-b\"), what: \"Reachable, but the data behind it is hours old — the case a status field alone gets wrong.\" },\n  { device: deviceById(\"air-1\"), what: \"Weak signal and a fault reported by the device itself.\" },\n  { device: deviceById(\"probe-c\"), what: \"Not heard from in days, and the battery was nearly flat when it was.\" },\n  { device: { ...deviceById(\"gateway-1\"), signal: undefined }, what: \"No signal figure reported. Not the same as a signal of zero.\" },\n  { device: deviceById(\"meter-1\"), what: \"Mid-update. Its last reading is not its current reading.\" },\n];\n\nexport function ConnectionTroubleshootingExample() {\n  return (\n    <div className=\"grid gap-3 md:grid-cols-2\">\n      {CASES.map(({ device, what }) => (\n        <div key={device.id} className=\"flex flex-col gap-3 rounded-2xl bg-card p-4 shadow-sm sm:p-5\">\n          <div className=\"flex items-start justify-between gap-3\">\n            <span className=\"text-title-md text-foreground\">{device.name}</span>\n            <DeviceStatusBadge status={device.status} />\n          </div>\n          <ConnectionHealth device={device} freshnessMs={10 * 60_000} now={DEMO_NOW} />\n          <p className=\"text-body-md text-muted-foreground\">{what}</p>\n        </div>\n      ))}\n    </div>\n  );\n}",
  "alert-inbox": "/** One-line rows need room for the message; below 768px the fuller list rows read better. */\nfunction useWide(): boolean {\n  const [wide, setWide] = React.useState(false);\n  React.useEffect(() => {\n    if (typeof window.matchMedia !== \"function\") return;\n    const media = window.matchMedia(\"(min-width: 768px)\");\n    const read = () => setWide(media.matches);\n    read();\n    media.addEventListener?.(\"change\", read);\n    return () => media.removeEventListener?.(\"change\", read);\n  }, []);\n  return wide;\n}\n\nexport function AlertInboxExample() {\n  const wide = useWide();\n  // Local demo state. Acknowledging here changes this component and nothing else — there is no\n  // request, no device, and no server. See the note on the page.\n  const [acknowledged, setAcknowledged] = React.useState<Record<string, string>>({});\n  const [showAcknowledged, setShowAcknowledged] = React.useState(false);\n\n  const alerts = DEMO_ALERTS.map((alert) =>\n    acknowledged[alert.id] ? { ...alert, acknowledgedAt: acknowledged[alert.id] } : alert,\n  );\n\n  // `activeAlerts` sorts newest first and, by default, leaves acknowledged ones out — so \"show\n  // acknowledged\" is a flag it already takes rather than a second code path here.\n  const visible = activeAlerts(alerts, { includeAcknowledged: showAcknowledged });\n  const loudest = highestAlertSeverity(alerts);\n\n  return (\n    <section aria-label=\"Alert inbox\" className=\"flex flex-col gap-4 rounded-2xl bg-card p-4 shadow-sm sm:p-6\">\n      <header className=\"flex flex-wrap items-center justify-between gap-3\">\n        <div className=\"flex flex-col gap-0.5\">\n          <p className=\"tabular-nums text-headline-md text-foreground\">\n            {visible.length} alert{visible.length === 1 ? \"\" : \"s\"}\n          </p>\n          {loudest ? <p className=\"text-body-md text-muted-foreground\">Loudest is {loudest}</p> : null}\n        </div>\n        <label className=\"flex min-h-11 cursor-pointer items-center gap-3 rounded-full bg-muted/60 px-4 text-body-md text-foreground md:min-h-9\">\n          <input type=\"checkbox\" checked={showAcknowledged} onChange={(event) => setShowAcknowledged(event.target.checked)} className=\"size-5 rounded border-input\" />\n          Show acknowledged\n        </label>\n      </header>\n\n      {visible.length === 0 ? (\n        <p className=\"rounded-xl border-2 border-dashed border-border p-6 text-center text-body-md text-muted-foreground\">Nothing unacknowledged.</p>\n      ) : (\n        <ul className=\"m-0 flex list-none flex-col gap-2 p-0\">\n          {visible.map((alert) => (\n            <li key={alert.id}>\n              <AlertCard\n                alert={alert}\n                deviceName={deviceById(alert.deviceId).name}\n                now={DEMO_NOW}\n                variant={wide ? \"compact\" : \"list\"}\n                onAcknowledge={wide ? undefined : (target) => setAcknowledged((prev) => ({ ...prev, [target.id]: DEMO_NOW }))}\n                action={\n                  alert.acknowledgedAt || !wide ? null : (\n                    <button\n                      type=\"button\"\n                      onClick={() => setAcknowledged((prev) => ({ ...prev, [alert.id]: DEMO_NOW }))}\n                      className=\"inline-flex min-h-11 items-center rounded-full bg-muted px-4 text-body-md text-foreground hover:bg-muted/70 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring md:min-h-9\"\n                    >\n                      {/* Named, not an icon: \"Acknowledge\" beside a device name is what a screen\n                          reader announces, and a bare tick is not. */}\n                      <span className=\"sr-only\">Acknowledge alert: {alert.message}. </span>\n                      Acknowledge\n                    </button>\n                  )\n                }\n              />\n            </li>\n          ))}\n        </ul>\n      )}\n    </section>\n  );\n}",
  "device-dashboard": "/**\n * Everything below is LOCAL DEMO STATE.\n *\n * Toggling a device, moving a slider or acknowledging an alert changes a `useState` value in this\n * component and nothing else. `@kinetixui/iot` has no transport — no MQTT, no BLE, no WebSocket, no\n * HTTP client — so nothing here reaches a device, and a showcase that implied otherwise would be\n * advertising a capability the package does not have.\n */\nconst GROUPS = [\"All\", \"Cold store A\", \"Plant room\", \"Bay 2\"] as const;\ntype Group = (typeof GROUPS)[number];\n\n// The product supplies these. `@kinetixui/iot` hard-codes no mode vocabulary, because the same\n// control serves a chiller, an irrigation valve and a conveyor.\nconst MODES = [\n  { id: \"cool\", label: \"Cool\" },\n  { id: \"hold\", label: \"Hold\" },\n  { id: \"defrost\", label: \"Defrost\", description: \"Unavailable until the cycle completes\", unavailable: true },\n];\n\nexport function DeviceDashboardExample() {\n  const [group, setGroup] = React.useState<Group>(\"All\");\n  const [selectedId, setSelectedId] = React.useState<string>(\"probe-a\");\n  const [overrides, setOverrides] = React.useState<Record<string, KinetixDeviceStatus>>({});\n  const [acknowledged, setAcknowledged] = React.useState<Record<string, string>>({});\n  // Confirmed values — what the imaginary device has reported.\n  const [powered, setPowered] = React.useState<\"on\" | \"off\">(\"on\");\n  const [intensity, setIntensity] = React.useState(62);\n  const [target, setTarget] = React.useState(4);\n  const [mode, setMode] = React.useState(\"cool\");\n\n  // Requested values — what the user has asked for and the device has not confirmed yet.\n  const [pending, setPending] = React.useState<null | { kind: \"power\" | \"level\" | \"target\" | \"mode\"; value: string | number }>(null);\n\n  // A command that resolves after a beat, so the requested-versus-confirmed gap is visible rather\n  // than theoretical. A product would replace this with whatever its transport reports back.\n  React.useEffect(() => {\n    if (!pending) return;\n    const timer = setTimeout(() => {\n      if (pending.kind === \"power\") setPowered(pending.value as \"on\" | \"off\");\n      if (pending.kind === \"level\") setIntensity(pending.value as number);\n      if (pending.kind === \"target\") setTarget(pending.value as number);\n      if (pending.kind === \"mode\") setMode(pending.value as string);\n      setPending(null);\n    }, 1100);\n    return () => clearTimeout(timer);\n  }, [pending]);\n\n  const request = (kind: \"power\" | \"level\" | \"target\" | \"mode\", value: string | number) => setPending({ kind, value });\n\n  const devices: KinetixDevice[] = DEMO_DEVICES.map((device) =>\n    overrides[device.id] ? { ...device, status: overrides[device.id]! } : device,\n  );\n  const inGroup = group === \"All\" ? devices : devices.filter((device) => device.locationName === group);\n  const ordered = [...inGroup].sort(compareDeviceAttention);\n  const summary = summarizeDevices(inGroup);\n  const selected = deviceById(selectedId);\n\n  // One resolution for all four controls, so they cannot disagree about whether the device is\n  // reachable or a command is outstanding.\n  const control = resolveControlState({\n    deviceStatus: selected.status,\n    commandStatus: pending ? \"sent\" : undefined,\n  });\n  const alerts = DEMO_ALERTS.map((a) => (acknowledged[a.id] ? { ...a, acknowledgedAt: acknowledged[a.id] } : a));\n  const openAlerts = alerts.filter((a) => !a.acknowledgedAt);\n\n  return (\n    <div className=\"flex flex-col gap-4\">\n      {/* ---------------------------------------------------------------- header */}\n      <header className=\"flex flex-col gap-4 rounded-2xl bg-card p-4 shadow-sm sm:p-6\">\n        <div className=\"flex flex-wrap items-baseline justify-between gap-x-4 gap-y-2\">\n          <h3 className=\"text-headline-sm text-foreground\">Cold chain · Site 4</h3>\n          {/* A count, not a verdict. Whether two offline devices is fine depends on what they are. */}\n          <p className=\"text-body-md text-muted-foreground\">\n            {summary.total} device{summary.total === 1 ? \"\" : \"s\"} · {summary.needsAttention} needing attention ·{\" \"}\n            {openAlerts.length} open alert{openAlerts.length === 1 ? \"\" : \"s\"}\n          </p>\n        </div>\n\n        {/* The group selector every product surveyed puts here, generalised from \"rooms\". */}\n        <div role=\"tablist\" aria-label=\"Device group\" className=\"flex flex-wrap gap-2\">\n          {GROUPS.map((name) => (\n            <button\n              key={name}\n              role=\"tab\"\n              type=\"button\"\n              aria-selected={group === name}\n              onClick={() => setGroup(name)}\n              className={[\n                \"inline-flex min-h-11 shrink-0 items-center rounded-full px-4 text-body-md transition-colors duration-fast motion-reduce:transition-none md:min-h-9\",\n                \"focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring\",\n                group === name ? \"bg-primary font-semibold text-primary-foreground shadow-sm\" : \"bg-muted/60 text-foreground hover:bg-muted\",\n              ].join(\" \")}\n            >\n              {name}\n            </button>\n          ))}\n        </div>\n\n        <DeviceStateSummary devices={inGroup} />\n      </header>\n\n      {/* ---------------------------------------------------------------- fleet + detail */}\n      <div className=\"grid gap-4 xl:grid-cols-[minmax(0,1fr)_20rem]\">\n        <section aria-label=\"Devices\" className=\"grid grid-cols-[repeat(auto-fill,minmax(min(100%,16rem),1fr))] gap-3\">\n          {ordered.map((device) => {\n            const isSelected = device.id === selectedId;\n            return (\n              <DeviceCard\n                key={device.id}\n                device={device}\n                reading={DEMO_READINGS[device.id]}\n                now={DEMO_NOW}\n                className={isSelected ? \"ring-2 ring-primary ring-offset-2 ring-offset-background\" : \"\"}\n                action={\n                  <button\n                    type=\"button\"\n                    onClick={() => setSelectedId(device.id)}\n                    aria-pressed={isSelected}\n                    className=\"inline-flex min-h-11 items-center rounded-full bg-muted px-4 text-body-md text-foreground hover:bg-muted/70 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring md:min-h-9\"\n                  >\n                    <span className=\"sr-only\">Show details for {device.name}. </span>\n                    Details\n                  </button>\n                }\n              />\n            );\n          })}\n          {ordered.length === 0 ? (\n            <p className=\"rounded-xl border-2 border-dashed border-border p-6 text-body-md text-muted-foreground\">\n              No devices in this group.\n            </p>\n          ) : null}\n        </section>\n\n        {/* The detail panel: the tile-to-detail pattern, as a column beside the grid on wide screens\n            and a section below it on narrow ones. */}\n        <aside aria-label={`Detail: ${selected.name}`} className=\"flex flex-col gap-4 rounded-2xl bg-card p-4 shadow-sm sm:p-6\">\n          <div className=\"flex flex-col gap-1\">\n            <span className=\"text-body-md text-muted-foreground\">Selected device</span>\n            <span className=\"text-title-lg text-foreground\">{selected.name}</span>\n            <span className=\"text-body-md text-muted-foreground\">{selected.locationName}</span>\n          </div>\n\n          {/* The control layer, wired to LOCAL DEMO STATE.\n              A request is held for 1.1s before it \"confirms\", because that is what a device on a\n              real network does — and because the state worth showing is the one in between. Nothing\n              here reaches a device: `@kinetixui/iot` has no transport of any kind. */}\n          {/* `min-w-0` because a <fieldset> defaults to `min-inline-size: min-content` and will not shrink\n              below its widest child — which put a 370px panel inside a 320px column. */}\n          <fieldset className=\"flex min-w-0 flex-col gap-4 border-0 border-t border-border p-0 pt-4\">\n            <legend className=\"sr-only\">Demonstration controls for {selected.name}</legend>\n\n            <DevicePowerControl\n              state={powered}\n              requested={pending?.kind === \"power\" ? (pending.value as \"on\" | \"off\") : undefined}\n              control={control}\n              label={`${selected.name} power`}\n              onToggle={(next) => request(\"power\", next)}\n            />\n\n            <DeviceLevelControl\n              value={intensity}\n              target={pending?.kind === \"level\" ? (pending.value as number) : undefined}\n              control={control}\n              label=\"Intensity\"\n              unit=\"%\"\n              onCommit={(next) => request(\"level\", next)}\n            />\n\n            <DeviceSetpointControl\n              current={selected.id === \"probe-a\" ? 4.2 : undefined}\n              target={target}\n              requestedTarget={pending?.kind === \"target\" ? (pending.value as number) : undefined}\n              min={-20}\n              max={25}\n              unit=\"°C\"\n              label=\"Target temperature\"\n              control={control}\n              onCommit={(next) => request(\"target\", next)}\n            />\n\n            <DeviceModeControl\n              modes={MODES}\n              value={mode}\n              requested={pending?.kind === \"mode\" ? (pending.value as string) : undefined}\n              control={control}\n              label=\"Operating mode\"\n              onSelect={(id) => request(\"mode\", id)}\n            />\n\n            <div className=\"flex flex-col gap-1.5\">\n              <span className=\"text-title-md text-foreground\">Simulate a state</span>\n              <div className=\"flex flex-wrap gap-1.5\">\n                {([\"online\", \"syncing\", \"stale\", \"offline\", \"error\"] as const).map((status) => (\n                  <button\n                    key={status}\n                    type=\"button\"\n                    onClick={() => setOverrides((prev) => ({ ...prev, [selected.id]: status }))}\n                    className=\"inline-flex min-h-11 items-center rounded-full bg-muted/60 px-4 text-body-md text-foreground transition-colors duration-fast hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring motion-reduce:transition-none md:min-h-9\"\n                  >\n                    {describeDeviceStatus(status)}\n                  </button>\n                ))}\n              </div>\n              {/* One polite live region for the whole panel, announced only when the reader acted.\n                  Telemetry updates are deliberately NOT announced — a dashboard that narrates every\n                  reading is a dashboard nobody can use with a screen reader. */}\n              <p aria-live=\"polite\" className=\"text-body-sm text-muted-foreground\">\n                {overrides[selected.id] ? `${selected.name} is now ${describeDeviceStatus(overrides[selected.id]!).toLowerCase()}.` : \"\"}\n              </p>\n            </div>\n          </fieldset>\n        </aside>\n      </div>\n\n      {/* ---------------------------------------------------------------- telemetry */}\n      <section aria-label=\"Telemetry\" className=\"grid grid-cols-[repeat(auto-fit,minmax(min(100%,14rem),1fr))] gap-3\">\n        <TelemetryCard series={DEMO_SERIES.temperature} metric=\"Temperature\" precision={1} now={DEMO_NOW} />\n        <TelemetryCard series={DEMO_SERIES.humidity} metric=\"Humidity\" now={DEMO_NOW} />\n        <TelemetryCard series={DEMO_SERIES.load} metric=\"Load\" precision={1} now={DEMO_NOW} />\n        <TelemetryCard series={DEMO_SERIES.airQuality} metric=\"PM2.5\" now={DEMO_NOW} />\n      </section>\n\n      {/* ---------------------------------------------------------------- alerts + activity */}\n      <div className=\"grid gap-4 lg:grid-cols-2\">\n        <section aria-label=\"Alerts\" className=\"flex flex-col gap-3 rounded-2xl bg-card p-4 shadow-sm sm:p-6\">\n          <h4 className=\"text-title-md text-foreground\">Alerts</h4>\n          {openAlerts.length === 0 ? (\n            <p className=\"rounded-xl border-2 border-dashed border-border p-4 text-body-md text-muted-foreground\">\n              Nothing unacknowledged.\n            </p>\n          ) : (\n            <ul className=\"flex flex-col gap-2\">\n              {openAlerts.map((alert) => (\n                <li key={alert.id}>\n                  <AlertCard\n                    alert={alert}\n                    deviceName={deviceById(alert.deviceId).name}\n                    now={DEMO_NOW}\n                    onAcknowledge={(target) => setAcknowledged((prev) => ({ ...prev, [target.id]: DEMO_NOW }))}\n                  />\n                </li>\n              ))}\n            </ul>\n          )}\n        </section>\n\n        <section aria-label=\"Activity\" className=\"flex flex-col gap-3 rounded-2xl bg-card p-4 shadow-sm sm:p-6\">\n          <h4 className=\"text-title-md text-foreground\">Recent commands</h4>\n          {/* The time-rail activity list: the timestamp gutter is the structure, not a trailing note. */}\n          <ul className=\"flex flex-col\">\n            {DEMO_COMMANDS.map((command) => (\n              <li key={command.id} className=\"grid grid-cols-[auto_1fr] gap-3 border-s border-border ps-4 pb-4 last:pb-0\">\n                <span aria-hidden=\"true\" className=\"-ms-5 mt-1.5 size-2 rounded-full bg-border\" />\n                <span className=\"flex flex-col gap-0.5\">\n                  <span className=\"text-body-md text-foreground\">{deviceById(command.deviceId).name}</span>\n                  <CommandStatus command={command} showName now={DEMO_NOW} />\n                </span>\n              </li>\n            ))}\n          </ul>\n        </section>\n      </div>\n    </div>\n  );\n}",
  "connected-space": "/**\n * A connected space: zones, the devices in one of them, and the automations that run it.\n *\n * Everything below is LOCAL DEMO STATE, and every device, zone and routine here is invented.\n * Toggling something changes a `useState` value in this component. `@kinetixui/iot` has no transport\n * — no MQTT, no BLE, no Matter, no WebSocket — so nothing reaches a device, and a showcase implying\n * otherwise would be advertising a capability the package does not have.\n *\n * The one behaviour worth watching: a command is held for 1.1s before it confirms. During that\n * window the control shows what you **asked for** as clearly distinct from what the device has\n * **reported**, which is the gap most device UIs paper over with an optimistic update.\n */\nconst NOW = \"2026-01-01T12:00:00.000Z\";\nconst ago = (ms: number) => new Date(Date.parse(NOW) - ms).toISOString();\nconst ahead = (ms: number) => new Date(Date.parse(NOW) + ms).toISOString();\n\nconst ZONES = [\n  { id: \"hall\", name: \"Packing hall\", kind: \"Zone\", deviceCount: 12, activeCount: 7, category: \"light\" as const, summary: \"21°C · 48% RH\" },\n  { id: \"field\", name: \"North field\", kind: \"Zone\", deviceCount: 8, activeCount: 4, attentionCount: 1, category: \"pump\" as const, summary: \"3 of 8 valves open\" },\n  { id: \"store\", name: \"Cold store\", kind: \"Site\", deviceCount: 5, activeCount: 0, category: \"sensor\" as const, summary: \"All within range\" },\n];\n\nconst FIXTURES: KinetixDevice[] = [\n  { id: \"bench\", name: \"Bench lamps\", type: \"light\", status: \"online\", lastSeenAt: ago(30_000), locationName: \"Packing hall\" },\n  { id: \"bay\", name: \"Loading bay flood\", type: \"light\", status: \"online\", lastSeenAt: ago(90_000), locationName: \"Packing hall\" },\n  { id: \"yard\", name: \"Yard flood\", type: \"light\", status: \"offline\", lastSeenAt: ago(3 * 3_600_000), locationName: \"Packing hall\" },\n];\n\nconst ROUTINES: KinetixAutomation[] = [\n  {\n    id: \"shutdown\",\n    name: \"End of shift\",\n    kind: \"scene\",\n    status: \"idle\",\n    enabled: true,\n    actions: \"9 lights off, 2 doors locked\",\n    lastRunAt: ago(14 * 3_600_000),\n  },\n  {\n    id: \"irrigation\",\n    name: \"Evening irrigation\",\n    kind: \"schedule\",\n    status: \"idle\",\n    enabled: true,\n    trigger: \"Weekdays 18:30\",\n    actions: \"2 valves, 40 min\",\n    lastRunAt: ago(20 * 3_600_000),\n    nextRunAt: ahead(6 * 3_600_000),\n  },\n  {\n    id: \"frost\",\n    name: \"Frost protection\",\n    kind: \"routine\",\n    status: \"failed\",\n    enabled: true,\n    trigger: \"Outside below 2°C\",\n    actions: \"Circulation pump\",\n    lastRunAt: ago(90 * 60_000),\n    errorMessage: \"Pump did not acknowledge\",\n  },\n];\n\ntype Pending = { id: string; kind: \"power\" | \"level\"; value: string | number };\n\nexport function ConnectedSpaceExample() {\n  const [zoneId, setZoneId] = React.useState(\"hall\");\n  const [power, setPower] = React.useState<Record<string, \"on\" | \"off\">>({ bench: \"on\", bay: \"off\", yard: \"on\" });\n  const [level, setLevel] = React.useState<Record<string, number>>({ bench: 100, bay: 40, yard: 70 });\n  const [pending, setPending] = React.useState<Pending | null>(null);\n  const [routines, setRoutines] = React.useState(ROUTINES);\n  const [openId, setOpenId] = React.useState<string | null>(\"bench\");\n\n  React.useEffect(() => {\n    if (!pending) return;\n    const timer = setTimeout(() => {\n      if (pending.kind === \"power\") setPower((p) => ({ ...p, [pending.id]: pending.value as \"on\" | \"off\" }));\n      if (pending.kind === \"level\") setLevel((l) => ({ ...l, [pending.id]: pending.value as number }));\n      setPending(null);\n    }, 1100);\n    return () => clearTimeout(timer);\n  }, [pending]);\n\n  const controlFor = (device: KinetixDevice) =>\n    resolveControlState({\n      deviceStatus: device.status,\n      commandStatus: pending?.id === device.id ? \"sent\" : undefined,\n    });\n\n  const zone = ZONES.find((z) => z.id === zoneId) ?? ZONES[0]!;\n\n  return (\n    <section aria-label=\"Connected space\" className=\"flex flex-col gap-6 sm:gap-8\">\n      {/* ------------------------------------------------------------------ zones */}\n      <div>\n        <h3 className=\"mb-3 text-title-lg text-foreground\">Zones</h3>\n        <div className=\"grid grid-cols-[repeat(auto-fit,minmax(min(100%,15rem),1fr))] gap-3\">\n          {ZONES.map((z) => (\n            <DeviceGroupCard\n              key={z.id}\n              name={z.name}\n              kind={z.kind}\n              deviceCount={z.deviceCount}\n              activeCount={z.activeCount}\n              attentionCount={z.attentionCount}\n              category={z.category}\n              summary={z.summary}\n              onSelect={() => setZoneId(z.id)}\n              className={z.id === zoneId ? \"ring-2 ring-ring ring-offset-2 ring-offset-background\" : undefined}\n            />\n          ))}\n        </div>\n      </div>\n\n      {/* ------------------------------------------------------------- the devices */}\n      <div>\n        <h3 className=\"mb-3 text-title-lg text-foreground\">{zone.name} — fixtures</h3>\n        <div className=\"grid grid-cols-[repeat(auto-fit,minmax(min(100%,16rem),1fr))] gap-3\">\n          {FIXTURES.map((device) => {\n            const control = controlFor(device);\n            const requestedPower = pending?.id === device.id && pending.kind === \"power\" ? (pending.value as \"on\" | \"off\") : undefined;\n            const on = power[device.id] === \"on\";\n\n            return (\n              <DeviceControlCard\n                key={device.id}\n                device={device}\n                active={on && device.status === \"online\"}\n                control={control}\n                open={openId === device.id}\n                onOpenChange={(next) => setOpenId(next ? device.id : null)}\n                statusLine={\n                  device.status === \"offline\"\n                    ? \"Last reachable 3h ago\"\n                    : requestedPower\n                      ? `Turning ${requestedPower}`\n                      : on\n                        ? `${level[device.id]}% brightness`\n                        : \"Off\"\n                }\n                primaryControl={\n                  <DevicePowerControl\n                    state={power[device.id]}\n                    requested={requestedPower}\n                    control={control}\n                    label={`${device.name} power`}\n                    showLabel={false}\n                    onToggle={(next) => setPending({ id: device.id, kind: \"power\", value: next })}\n                  />\n                }\n                expanded={\n                  <DeviceLevelControl\n                    value={level[device.id]}\n                    target={pending?.id === device.id && pending.kind === \"level\" ? (pending.value as number) : undefined}\n                    control={control}\n                    label={`${device.name} brightness`}\n                    unit=\"%\"\n                    onCommit={(next) => setPending({ id: device.id, kind: \"level\", value: next })}\n                  />\n                }\n              />\n            );\n          })}\n        </div>\n      </div>\n\n      {/* ---------------------------------------------------------------- routines */}\n      <div>\n        <h3 className=\"mb-3 text-title-lg text-foreground\">Automations</h3>\n        <div className=\"grid grid-cols-[repeat(auto-fit,minmax(min(100%,17rem),1fr))] gap-3\">\n          {routines.map((automation) => (\n            <RoutineCard\n              key={automation.id}\n              automation={automation}\n              now={NOW}\n              onToggleEnabled={(next) =>\n                setRoutines((rs) => rs.map((r) => (r.id === automation.id ? { ...r, enabled: next } : r)))\n              }\n              onRun={() => {\n                // A run that finishes on its own, so \"running\" is a state you can actually watch.\n                setRoutines((rs) => rs.map((r) => (r.id === automation.id ? { ...r, status: \"running\" } : r)));\n                setTimeout(\n                  () =>\n                    setRoutines((rs) =>\n                      rs.map((r) => (r.id === automation.id ? { ...r, status: \"idle\", lastRunAt: NOW } : r)),\n                    ),\n                  1800,\n                );\n              }}\n            />\n          ))}\n        </div>\n      </div>\n    </section>\n  );\n}"
};
